-- 5-bo'lim: Reklama kampaniyalari — 10 ta dars: oddiy (104 savol) va rasmli (118 savol) testlar. SQL Editor'da bir marta Run qiling.

insert into public.tests(id, section, section_order, lesson_order, title, questions, published) values (
'5-1', '5. Reklama kampaniyalari', 5, 1, '1. Reklama turlari', $json$[{"id": "q1", "prompt": "Reklama yaratish uchun Ads Manager'ga qayerdan kiriladi?", "options": [{"id": "a", "text": "Business Manager'dagi menyu (uch chiziqli «гамбургер» belgisi) orqali «Ads Manager» ochiladi"}, {"id": "b", "text": "Instagram profilidagi «Редактировать профиль» tugmasi orqali"}, {"id": "c", "text": "Gmail pochtadagi xat orqali"}, {"id": "d", "text": "Facebook sahifadagi «Создать публикацию» orqali"}], "correct_option_id": "a", "explanation": "Ustoz Business Manager menyusidan «Ads Manager»ni yangi oynada ochdi."}, {"id": "q2", "prompt": "Ustoz qaysi reklama akkauntidan reklama yurgizmaslikni aytdi?", "options": [{"id": "a", "text": "Business Manager ichidagi reklama akkauntidan"}, {"id": "b", "text": "Hech qaysi akkauntdan, reklama faqat telefondan beriladi"}, {"id": "c", "text": "Sahifa adminining akkauntidan"}, {"id": "d", "text": "Shaxsiy reklama akkauntidan. Reklama Business Manager ichida yaratilgan reklama akkauntidan yurgiziladi"}], "correct_option_id": "d", "explanation": "Ads Manager ochilganda tepada shaxsiy akkaunt turishi mumkin. Uni BM ichidagi reklama akkauntiga almashtirib olish kerak."}, {"id": "q3", "prompt": "Yangi reklama yaratish uchun Ads Manager'da qaysi tugma bosiladi?", "options": [{"id": "a", "text": "Yashil «Создать» (Create) tugmasi"}, {"id": "b", "text": "«Отчеты» (Reports)"}, {"id": "c", "text": "«Дублировать» (Duplicate)"}, {"id": "d", "text": "«Редактировать» (Edit)"}], "correct_option_id": "a", "explanation": "«Создать» bosilganda 6 xil maqsadli reklama turi chiqadi."}, {"id": "q4", "prompt": "«Создать» bosilganda nechta reklama maqsadi (turi) chiqadi?", "options": [{"id": "a", "text": "4 ta"}, {"id": "b", "text": "6 ta"}, {"id": "c", "text": "3 ta"}, {"id": "d", "text": "10 ta"}], "correct_option_id": "b", "explanation": "Узнаваемость, Трафик, Вовлеченность, Лиды, Продвижение приложения va Продажи."}, {"id": "q5", "prompt": "«Требуется информация об аккаунте» (Account information required) yozuvi chiqib, sahifa tanlanmayapti. Ustoz bu muammoni qanday hal qildi?", "options": [{"id": "a", "text": "Reklama akkauntini o'chirib tashladi"}, {"id": "b", "text": "Business Manager sozlamalarida o'ziga sahifadan foydalanish ruxsatini (to'liq kirish) berdi"}, {"id": "c", "text": "Yangi Facebook sahifa ochdi"}, {"id": "d", "text": "Instagram'dan chiqib, qayta kirdi"}], "correct_option_id": "b", "explanation": "Sahifa BMga qo'shilgan bo'lsa ham, odamga uni boshqarish ruxsati berilmagan bo'lishi mumkin. Shuning uchun BM sozlamalarida sahifaga kirish huquqi biriktiriladi."}, {"id": "q6", "prompt": "«Узнаваемость» (Awareness) maqsadi nima uchun ishlatiladi?", "options": [{"id": "a", "text": "Reklamani iloji boricha ko'p odamga ko'rsatish va brendni tanitish uchun: ko'proq qamrov, video ko'rishlar, eslab qolish"}, {"id": "b", "text": "Saytdan to'g'ridan-to'g'ri sotuv qilish uchun"}, {"id": "c", "text": "Ilovani yuklab olishlar soni uchun"}, {"id": "d", "text": "Anketa orqali telefon raqam yig'ish uchun"}], "correct_option_id": "a", "explanation": "Masalan, yangi brendni yoki do'konni ko'p odamga tanitish kerak bo'lganda ishlatiladi."}, {"id": "q7", "prompt": "«Трафик» (Traffic) maqsadining vazifasi nima?", "options": [{"id": "a", "text": "Faqat telefon raqam yig'ish"}, {"id": "b", "text": "Odamlarni kerakli manzilga yuborish: saytga, ilovaga, Instagram profilga yoki messenjerga"}, {"id": "c", "text": "Faqat ilova o'rnatishlarini ko'paytirish"}, {"id": "d", "text": "Faqat layk va izohlarni ko'paytirish"}], "correct_option_id": "b", "explanation": "Trafikda Facebook ko'p klik olib kelishga harakat qiladi. Lekin ular sifatli mijoz bo'lmasligi ham mumkin."}, {"id": "q8", "prompt": "«Трафик» va «Вовлеченность» (Engagement) maqsadlarining farqi nimada?", "options": [{"id": "a", "text": "Farqi yo'q, ikkalasi bir xil ishlaydi"}, {"id": "b", "text": "Trafik odamni faqat manzilga olib boradi. Вовлеченность esa odam o'sha yerda harakat qilishini kutadi: xabar yozish, layk bosish, izoh qoldirish, video ko'rish"}, {"id": "c", "text": "Trafik faqat Instagram'da, Вовлеченность faqat Facebook'da ishlaydi"}, {"id": "d", "text": "Вовлеченность faqat ilovalar uchun"}], "correct_option_id": "b", "explanation": "Ustoz shunday tushuntirdi: trafik shunchaki yuboradi, вовлеченность esa o'zaro muloqotni kutadi."}, {"id": "q9", "prompt": "«Продвижение приложения» (App promotion) maqsadi nima uchun kerak?", "options": [{"id": "a", "text": "Telefon ilovasini Play Market yoki App Store'dan yuklab olishlarini ko'paytirish uchun"}, {"id": "b", "text": "Do'konga telefon qilishlarni ko'paytirish uchun"}, {"id": "c", "text": "Saytga kirishlarni ko'paytirish uchun"}, {"id": "d", "text": "Instagram obunachilarni ko'paytirish uchun"}], "correct_option_id": "a", "explanation": "Ustoz bu maqsadni deyarli ishlatmasligini aytdi, chunki u ilova reklamasi bilan ishlamaydi."}, {"id": "q10", "prompt": "Ustozning aytishicha, u ishining taxminan 90 foizida qaysi maqsadlardan foydalanadi?", "options": [{"id": "a", "text": "«Лиды» (Leads) va «Продажи» (Sales)"}, {"id": "b", "text": "«Узнаваемость» va «Трафик»"}, {"id": "c", "text": "«Вовлеченность» va «Продвижение приложения»"}, {"id": "d", "text": "Faqat «Трафик»"}], "correct_option_id": "a", "explanation": "Lid va sotuv maqsadlari to'g'ridan-to'g'ri mijoz olib keladi. Trafik va вовлеченностьni u kamdan-kam, masalan obunachi yoki video ko'rishlarni ko'paytirish uchun ishlatadi."}]$json$::jsonb, true)
on conflict (id) do update set title = excluded.title, questions = excluded.questions, section = excluded.section, section_order = excluded.section_order, lesson_order = excluded.lesson_order;

insert into public.tests(id, section, section_order, lesson_order, title, questions, published) values (
'5-2', '5. Reklama kampaniyalari', 5, 2, '2. Kampaniya bosqichlari', $json$[{"id": "q1", "prompt": "Har bir reklama kampaniyasi nechta bosqichdan iborat?", "options": [{"id": "a", "text": "2 ta: kampaniya va reklama"}, {"id": "b", "text": "Faqat bitta bosqich bor"}, {"id": "c", "text": "3 ta: «Кампания» (Campaign) → «Группа объявлений» (Ad set) → «Объявление» (Ad)"}, {"id": "d", "text": "4 ta: kampaniya, auditoriya, byudjet, reklama"}], "correct_option_id": "c", "explanation": "Kampaniya ichida reklama guruhi, guruh ichida esa reklamaning o'zi bo'ladi."}, {"id": "q2", "prompt": "«Кампания» (Campaign) bosqichida asosan nima tanlanadi?", "options": [{"id": "a", "text": "Reklamaning maqsadi (masalan, «Лиды» yoki «Трафик»)"}, {"id": "b", "text": "Reklama rasmi va matni"}, {"id": "c", "text": "Auditoriyaning yoshi va jinsi"}, {"id": "d", "text": "Kunlik byudjet"}], "correct_option_id": "a", "explanation": "Kampaniya bosqichida reklamadan nima kutilayotgani, ya'ni maqsad tanlanadi."}, {"id": "q3", "prompt": "«Группа объявлений» (Ad set) bosqichida nimalar sozlanadi?", "options": [{"id": "a", "text": "Faqat reklama matni"}, {"id": "b", "text": "Faqat sayt havolasi"}, {"id": "c", "text": "Faqat reklama maqsadi"}, {"id": "d", "text": "Byudjet, auditoriya (kimga ko'rsatiladi) va joylashuvlar (qayerda ko'rsatiladi)"}], "correct_option_id": "d", "explanation": "Masalan, kuniga qancha sarflash, qaysi shahar, yosh va jinsga ko'rsatish, Instagram stories yoki lentada chiqishi shu yerda belgilanadi."}, {"id": "q4", "prompt": "«Объявление» (Ad) bosqichida nima qo'yiladi?", "options": [{"id": "a", "text": "Reklama maqsadi"}, {"id": "b", "text": "Auditoriyaning qiziqishlari"}, {"id": "c", "text": "Video yoki rasm, reklama matni va odam qayerga borishi (sayt, Instagram, Facebook havolasi)"}, {"id": "d", "text": "Kunlik byudjet"}], "correct_option_id": "c", "explanation": "Bu reklamaning odamlarga ko'rinadigan qismi: kreativ, matn va havola."}, {"id": "q5", "prompt": "Har bir bosqichning sozlamalarini o'zgartirish uchun qaysi tugma bosiladi?", "options": [{"id": "a", "text": "«Создать» (Create)"}, {"id": "b", "text": "«Изменить» (Edit)"}, {"id": "c", "text": "«Опубликовать» (Publish)"}, {"id": "d", "text": "«Удалить» (Delete)"}], "correct_option_id": "b", "explanation": "Kampaniya, reklama guruhi va reklamaning har birida alohida «Изменить» tugmasi bor."}, {"id": "q6", "prompt": "Ustoz nega kampaniya, guruh va reklamaga aniq nom berishni maslahat berdi?", "options": [{"id": "a", "text": "Keyin ko'p reklamalar orasida chalkashmasdan, qaysi biri nima ekanini tez topish uchun"}, {"id": "b", "text": "Nomsiz reklama Facebook tomonidan bloklanadi"}, {"id": "c", "text": "Nom reklama narxini arzonlashtiradi"}, {"id": "d", "text": "Nom reklamada odamlarga ko'rinadi"}], "correct_option_id": "a", "explanation": "Masalan, kampaniya nomiga maqsad va mahsulot yoziladi: «Lead Dyson»."}, {"id": "q7", "prompt": "Bitta kampaniya ichida nechta reklama guruhi (Ad set) bo'lishi mumkin?", "options": [{"id": "a", "text": "Faqat bitta"}, {"id": "b", "text": "Umuman bo'lmaydi, faqat reklama bo'ladi"}, {"id": "c", "text": "Faqat ikkita"}, {"id": "d", "text": "Bir nechta: har birida alohida auditoriya va byudjet bo'lishi mumkin"}], "correct_option_id": "d", "explanation": "Masalan, bitta kampaniyada 25–30 yoshli ayollarga va 35+ yoshli ayollarga alohida guruh ochiladi."}, {"id": "q8", "prompt": "Ustoz ikkinchi reklama guruhini qanday yaratdi?", "options": [{"id": "a", "text": "Yangi kampaniyani noldan yaratdi"}, {"id": "b", "text": "Birinchi guruhni o'chirib, qaytadan yozdi"}, {"id": "c", "text": "Birinchi guruhni «Дублировать» (Duplicate) qilib, nusxasining auditoriya va byudjetini o'zgartirdi"}, {"id": "d", "text": "Reklama akkauntini almashtirdi"}], "correct_option_id": "c", "explanation": "Nusxada yoshni 35+ qilib, byudjetni kuniga 3 dollarga tushirdi. Kampaniya bitta qoldi, guruhlar ikkita bo'ldi."}, {"id": "q9", "prompt": "Nega bitta reklama guruhi ichida bir nechta reklama (video, rasm) qo'yiladi?", "options": [{"id": "a", "text": "Reklama narxi shunda arzonlashadi"}, {"id": "b", "text": "Facebook kamida 5 ta reklama talab qiladi"}, {"id": "c", "text": "Bittasi bloklansa, boshqasi ko'rsatilishi uchun"}, {"id": "d", "text": "Qaysi kreativ yaxshiroq natija berishini sinash uchun: bir muddatdan keyin qaysi biri arzonroq va ko'proq lid olib kelgani ko'rinadi"}], "correct_option_id": "d", "explanation": "Oldindan qaysi reklama yaxshi ishlashini bilib bo'lmaydi. Shuning uchun turli videolar va rasmlar sinab ko'riladi."}, {"id": "q10", "prompt": "Darsdagi misolda birinchi reklama guruhining sozlamalari qanday edi?", "options": [{"id": "a", "text": "18–65 yoshli erkaklar, kuniga 50 dollar"}, {"id": "b", "text": "25–30 yoshli ayollar, kuniga 5 dollar"}, {"id": "c", "text": "Faqat Toshkentdagi o'smirlar, kuniga 1 dollar"}, {"id": "d", "text": "Hamma odamlar, byudjetsiz"}], "correct_option_id": "b", "explanation": "Dyson soch quritgichi uchun auditoriya ayollar bo'lgani uchun shunday tanlandi."}]$json$::jsonb, true)
on conflict (id) do update set title = excluded.title, questions = excluded.questions, section = excluded.section, section_order = excluded.section_order, lesson_order = excluded.lesson_order;

insert into public.tests(id, section, section_order, lesson_order, title, questions, published) values (
'5-3', '5. Reklama kampaniyalari', 5, 3, '3. Lead (Lid) kampaniyasi', $json$[{"id": "q1", "prompt": "Saytga lid yig'ish kampaniyasini yaratishda birinchi qaysi maqsad tanlanadi?", "options": [{"id": "a", "text": "«Лиды» (Leads)"}, {"id": "b", "text": "«Продажи» (Sales)"}, {"id": "c", "text": "«Узнаваемость» (Awareness)"}, {"id": "d", "text": "«Трафик» (Traffic)"}], "correct_option_id": "a", "explanation": "«Создать» > «Лиды» > «Продолжить». Keyin sozlamalar qo'lda tanlanadi."}, {"id": "q2", "prompt": "Ustoz kampaniya nomiga nima yozishni maslahat berdi?", "options": [{"id": "a", "text": "Maqsad va reklama qilinayotgan mahsulot nomini, masalan «Dyson fen lead»"}, {"id": "b", "text": "Faqat bugungi sanani"}, {"id": "c", "text": "Hech narsa, nom shart emas"}, {"id": "d", "text": "O'z ismini"}], "correct_option_id": "a", "explanation": "Bitta akkauntda bir nechta mahsulot reklama qilinsa, nomga qarab chalkashmaysiz."}, {"id": "q3", "prompt": "Lid saytda qoldirilishi uchun «Место конверсии» (Conversion location) qismida nima tanlandi?", "options": [{"id": "a", "text": "«Сайт» (Website)"}, {"id": "b", "text": "«Моментальные формы» (Instant forms)"}, {"id": "c", "text": "«Звонки» (Calls)"}, {"id": "d", "text": "«Приложение» (App)"}], "correct_option_id": "a", "explanation": "Reklamadagi tugma bosilganda odam saytga o'tadi va u yerda lid qoldiradi."}, {"id": "q4", "prompt": "«Цель результативности» (Performance goal) qismida nega «Максимальное число кликов» emas, «Максимальное число конверсий» (Maximize conversions) tanlandi?", "options": [{"id": "a", "text": "Kliklar pullik, konversiyalar bepul"}, {"id": "b", "text": "Konversiya tanlansa, reklama tekshiruvdan o'tmaydi"}, {"id": "c", "text": "Klik ko'p bo'lsa ham, lid kam bo'lishi mumkin. Konversiya tanlansa, Facebook lid qoldiradigan odamlarni qidiradi"}, {"id": "d", "text": "Farqi yo'q, ikkalasi bir xil"}], "correct_option_id": "c", "explanation": "Maqsad lid bo'lgani uchun Facebookka aynan shu harakatni bajaradigan odamlarni topish vazifasi beriladi."}, {"id": "q5", "prompt": "Kerakli pixel ro'yxatda chiqmadi. Ustoz nima qildi?", "options": [{"id": "a", "text": "Business Manager sozlamalarida pixelga reklama akkauntini (va o'ziga ruxsat) biriktirdi"}, {"id": "b", "text": "Pixel'siz davom etdi"}, {"id": "c", "text": "Yangi sayt ochdi"}, {"id": "d", "text": "Kampaniyani o'chirib, qaytadan yaratdi"}], "correct_option_id": "a", "explanation": "Pixel boshqa obyektlarga ulanmagan bo'lsa, reklama akkauntida ko'rinmaydi. Ulangandan keyin ro'yxatda paydo bo'ldi."}, {"id": "q6", "prompt": "«Событие конверсии» (Conversion event) qismida nega «Лид» (Lead) tanlandi?", "options": [{"id": "a", "text": "Ro'yxatdan o'tish eventi bilan bir xil bo'lgani uchun"}, {"id": "b", "text": "Saytga aynan Lead eventi o'rnatilgan va maqsad lid yig'ish"}, {"id": "c", "text": "Lead eventi reklamani bepul qiladi"}, {"id": "d", "text": "Bu yagona mavjud event bo'lgani uchun"}], "correct_option_id": "b", "explanation": "Pixelda qaysi event o'rnatilgan bo'lsa, shu ro'yxatda chiqadi. Kerakli harakatga mos eventni tanlash kerak."}, {"id": "q7", "prompt": "«Предельная цена за результат» (Cost per result goal) maydoniga, masalan, 30 sent yozilsa nima bo'ladi?", "options": [{"id": "a", "text": "Reklama 30 kun ishlaydi"}, {"id": "b", "text": "Har bir lid aniq 30 sent turadi"}, {"id": "c", "text": "Facebook har bir lidni 30 sentdan qimmatga olmaslikka harakat qiladi. Bu chegara juda past bo'lsa, reklama umuman sarflanmasligi mumkin"}, {"id": "d", "text": "Kunlik byudjet 30 sent bo'ladi"}], "correct_option_id": "c", "explanation": "Ustoz bu maydonni faqat haqiqiy raqamlarni bilgandan keyin ishlatishni maslahat berdi."}, {"id": "q8", "prompt": "«Дневной бюджет» (Daily budget) va «Бюджет на весь срок» (Lifetime budget) farqi nimada?", "options": [{"id": "a", "text": "Kunlik byudjet har kuni belgilangan summani sarflaydi. Umumiy byudjet esa tanlangan sanalar oralig'ida jami summani sarflaydi"}, {"id": "b", "text": "Kunlik byudjet faqat dam olish kunlari ishlaydi"}, {"id": "c", "text": "Umumiy byudjetni o'zgartirib bo'lmaydi"}, {"id": "d", "text": "Ikkalasi bir xil"}], "correct_option_id": "a", "explanation": "Masalan, 1–8-mart aksiyasi uchun umumiy 100 dollar qo'yilsa, Facebook uni shu kunlar orasida o'zi taqsimlaydi."}, {"id": "q9", "prompt": "Umumiy byudjet (Lifetime budget) qachon qulay?", "options": [{"id": "a", "text": "Reklama doimiy, to'xtovsiz ishlashi kerak bo'lganda"}, {"id": "b", "text": "Byudjet umuman bo'lmaganda"}, {"id": "c", "text": "Faqat ilova reklamasida"}, {"id": "d", "text": "Ma'lum sanalar oralig'idagi aksiya uchun, masalan 1-martdan 8-martgacha"}], "correct_option_id": "d", "explanation": "8-mart aksiyasi misolida reklama 8-mart tugashi bilan o'zi to'xtaydi."}, {"id": "q10", "prompt": "Kunlik byudjetli reklamani soat 22:30 da yoqsangiz qanday xavf bor?", "options": [{"id": "a", "text": "Byudjet ikki baravar ko'payadi"}, {"id": "b", "text": "Hech qanday xavf yo'q"}, {"id": "c", "text": "Facebook butun kunlik byudjetni qolgan 1,5 soatda sarflab yuborishi mumkin"}, {"id": "d", "text": "Reklama ertaga butunlay o'chib qoladi"}], "correct_option_id": "c", "explanation": "Shuning uchun boshlanish sanasini ertangi kun soat 00:00 ga qo'yish tavsiya qilinadi."}, {"id": "q11", "prompt": "Ustoz «1 million so'm berib, do'konda 1 daqiqada sarfla» misolini nima uchun keltirdi?", "options": [{"id": "a", "text": "Reklama 1 million so'mdan arzon bo'lmasligini aytish uchun"}, {"id": "b", "text": "Do'kon reklamasini qanday qilishni ko'rsatish uchun"}, {"id": "c", "text": "Kunlik byudjetni qisqa vaqtga qoldirsangiz, Facebook ham pulni shoshib, samarasiz sarflashini tushuntirish uchun"}, {"id": "d", "text": "Facebook so'mda to'lov olmasligini aytish uchun"}], "correct_option_id": "c", "explanation": "Butun kun bo'lsa, Facebook byudjetni o'ylab, eng foydali joylarga taqsimlaydi."}, {"id": "q12", "prompt": "Darsdagi auditoriya qanday sozlandi?", "options": [{"id": "a", "text": "Butun dunyo, 18–65 yoshli hamma"}, {"id": "b", "text": "Faqat Toshkentdagi erkaklar"}, {"id": "c", "text": "Faqat 18 yoshgacha bo'lganlar"}, {"id": "d", "text": "O'zbekiston, 25–35 yoshli ayollar"}], "correct_option_id": "d", "explanation": "Joylashuvni shahar va radius bilan ham tanlash mumkin, masalan Toshkent atrofida 40 km."}, {"id": "q13", "prompt": "Auditoriya hajmi va kunlik lidlar soni bo'yicha Facebook ko'rsatgan raqamlar qanday?", "options": [{"id": "a", "text": "O'tgan oyning statistikasi"}, {"id": "b", "text": "Raqobatchilarning natijalari"}, {"id": "c", "text": "Kafolatlangan aniq raqamlar"}, {"id": "d", "text": "Taxminiy raqamlar, aniq emas"}], "correct_option_id": "d", "explanation": "Ustoz bu raqamlar faqat taxminiy ekanini, haqiqiy natija boshqacha bo'lishini ta'kidladi."}, {"id": "q14", "prompt": "Joylashuvlar (Placements) qismida ustoz qaysi variantni qoldirdi?", "options": [{"id": "a", "text": "Faqat Instagram stories"}, {"id": "b", "text": "«Места размещения Advantage+» (Advantage+ placements): Facebook reklamani qayerda ko'rsatishni o'zi tanlaydi"}, {"id": "c", "text": "Faqat Facebook lentasi"}, {"id": "d", "text": "Faqat Audience Network"}], "correct_option_id": "b", "explanation": "Facebook qayerda natija yaxshiroq bo'lsa, byudjetni o'sha yerga ko'proq yo'naltiradi."}, {"id": "q15", "prompt": "Reklamadagi «Основной текст» (Primary text) va «Заголовок» (Headline) qayerda chiqadi?", "options": [{"id": "a", "text": "Sarlavha tepada, asosiy matn umuman ko'rinmaydi"}, {"id": "b", "text": "Ikkalasi faqat saytda ko'rinadi"}, {"id": "c", "text": "Asosiy matn rasm tepasida, sarlavha rasm ostida chiqadi"}, {"id": "d", "text": "Ikkalasi ham rasm ichiga yoziladi"}], "correct_option_id": "c", "explanation": "Ustoz sarlavhani qisqa va jalb qiluvchi qilib yozishni maslahat berdi, masalan «Ayolingizni baxtli qiling»."}]$json$::jsonb, true)
on conflict (id) do update set title = excluded.title, questions = excluded.questions, section = excluded.section, section_order = excluded.section_order, lesson_order = excluded.lesson_order;

insert into public.tests(id, section, section_order, lesson_order, title, questions, published) values (
'5-4', '5. Reklama kampaniyalari', 5, 4, '4. Brendni tanitish kampaniyasi', $json$[{"id": "q1", "prompt": "«Узнаваемость» (Awareness) kampaniyasining asosiy maqsadi nima?", "options": [{"id": "a", "text": "Reklamani iloji boricha ko'p odamga ko'rsatib, brendni tanitish"}, {"id": "b", "text": "Ilova o'rnatishlarini ko'paytirish"}, {"id": "c", "text": "Darhol sotuv olish"}, {"id": "d", "text": "Telefon raqamlar yig'ish"}], "correct_option_id": "a", "explanation": "Video yoki rasm iloji boricha ko'p odamga ko'rsatiladi, odamlar brendni eslab qoladi."}, {"id": "q2", "prompt": "Ustoz brend reklamasini nimaga o'xshatdi?", "options": [{"id": "a", "text": "Ko'chadagi billbordga: darhol natija bermaydi, lekin uzoq muddatda odamlar brendni eslab qoladi"}, {"id": "b", "text": "Telefon qo'ng'irog'iga"}, {"id": "c", "text": "SMS xabarnomaga"}, {"id": "d", "text": "Do'kondagi chegirma yorlig'iga"}], "correct_option_id": "a", "explanation": "Ingliz tili markazi misolida ham odamlar reklamani ko'rib, kerak bo'lganda o'sha markazni eslaydi."}, {"id": "q3", "prompt": "Brend reklamasida auditoriya sifatida ustoz nimani tanladi?", "options": [{"id": "a", "text": "Faqat bitta qiziqishni"}, {"id": "b", "text": "Saytga kirganlarni"}, {"id": "c", "text": "Faqat obunachilarni"}, {"id": "d", "text": "Broad: qiziqishlarsiz keng auditoriya"}], "correct_option_id": "d", "explanation": "Maqsad iloji boricha ko'p odamga ko'rsatish bo'lgani uchun Facebookka erkinlik beriladi."}, {"id": "q4", "prompt": "«Максимальный охват» (Maximize reach) va «Максимальное число показов» (Maximize impressions) farqi nimada?", "options": [{"id": "a", "text": "Показы bepul, охват pullik"}, {"id": "b", "text": "Охват faqat Instagram'da, показы faqat Facebook'da"}, {"id": "c", "text": "Охват reklamani iloji boricha ko'p alohida odamga ko'rsatadi. Показы esa reklamani ko'p marta ko'rsatadi, bitta odam uni bir necha marta ko'rishi mumkin"}, {"id": "d", "text": "Farqi yo'q"}], "correct_option_id": "c", "explanation": "Ustoz misoli: 500 000 kishiga 1 martadan yoki kamroq kishiga 2–3 martadan ko'rsatish."}, {"id": "q5", "prompt": "«Максимальный прирост запоминаемости рекламы» (Maximize ad recall lift) nima qiladi?", "options": [{"id": "a", "text": "Reklamani eng arzon joyga qo'yadi"}, {"id": "b", "text": "Reklamani faqat obunachilarga ko'rsatadi"}, {"id": "c", "text": "Reklamani uni eslab qolishi ehtimoli yuqori bo'lgan odamlarga ko'rsatadi"}, {"id": "d", "text": "Reklamani faqat yangi foydalanuvchilarga ko'rsatadi"}], "correct_option_id": "c", "explanation": "Bu brend reklamasi uchun foydali: odamlar ko'rgan reklamani esda saqlaydi."}, {"id": "q6", "prompt": "ThruPlay maqsadi tanlansa, Facebook reklamani kimlarga ko'rsatadi?", "options": [{"id": "a", "text": "Videoni faqat 2 soniya ko'radiganlarga"}, {"id": "b", "text": "Videoni 15 soniya yoki (qisqaroq bo'lsa) oxirigacha ko'radigan odamlarga"}, {"id": "c", "text": "Videoni ovozsiz ko'radiganlarga"}, {"id": "d", "text": "Faqat videoga izoh yozadiganlarga"}], "correct_option_id": "b", "explanation": "Video 15 soniyadan qisqa bo'lsa, oxirigacha ko'rganlar hisoblanadi."}, {"id": "q7", "prompt": "Ustoz reklama guruhini dublikat qilib, ikkinchisiga boshqa maqsad (masalan, показы) qo'yishni nega taklif qildi?", "options": [{"id": "a", "text": "Охват va показы natijalarini taqqoslab, qaysi biri yaxshiroq ishlashini sinash uchun"}, {"id": "b", "text": "Facebook ikkita guruhni talab qilgani uchun"}, {"id": "c", "text": "Birinchi guruh o'chib qolmasligi uchun"}, {"id": "d", "text": "Byudjetni bekorga sarflash uchun"}], "correct_option_id": "a", "explanation": "Har bir guruhga nomini aniq qo'yish kerak: qaysi guruhda охват, qaysisida показы ekani ko'rinib tursin."}, {"id": "q8", "prompt": "«Предельная ставка» (Bid cap) maydoniga masalan 1 dollar yozilsa nimani bildiradi?", "options": [{"id": "a", "text": "Reklama faqat 1 kun ishlaydi"}, {"id": "b", "text": "Har bir lid 1 dollar turadi"}, {"id": "c", "text": "Reklamani 1000 marta ko'rsatish uchun Facebook auksionda 1 dollardan ko'p to'lamaydi"}, {"id": "d", "text": "Kunlik byudjet 1 dollar bo'ladi"}], "correct_option_id": "c", "explanation": "Raqobatchilar ko'proq taklif qilsa, reklamangiz ko'rsatilmay qolishi mumkin. Shuning uchun bu maydon ehtiyotkorlik bilan ishlatiladi."}, {"id": "q9", "prompt": "Ustozning aytishicha, brendni tanitish (Узнаваемость) boshqa maqsadlarga nisbatan qanday turadi?", "options": [{"id": "a", "text": "Bepul"}, {"id": "b", "text": "Eng arzon: kichik byudjetga ko'p odamga ko'rsatiladi"}, {"id": "c", "text": "Eng qimmat"}, {"id": "d", "text": "Lidlar bilan bir xil narxda"}], "correct_option_id": "b", "explanation": "Kuniga 5 dollarga taxminan 19 000 dan 56 000 gacha odamga yetib borish ko'rsatildi."}, {"id": "q10", "prompt": "«Аудитория Advantage+» (Advantage+ audience) qanday ishlaydi?", "options": [{"id": "a", "text": "Faqat bir shaharda ishlaydi"}, {"id": "b", "text": "Faqat obunachilarga ko'rsatadi"}, {"id": "c", "text": "Facebook auditoriyani o'zi tanlaydi, lekin siz minimal yosh kabi cheklovlarni (controls) qo'yishingiz mumkin"}, {"id": "d", "text": "Auditoriyani faqat qo'lda tanlash mumkin"}], "correct_option_id": "c", "explanation": "Masalan, Facebook o'zi qidiradi, lekin 21 yoshdan kichiklarga ko'rsatmaydi."}, {"id": "q11", "prompt": "Ustoz auditoriyada til (o'zbek yoki rus) tanlash haqida nima dedi?", "options": [{"id": "a", "text": "Til tanlanmasa, reklama ishlamaydi"}, {"id": "b", "text": "Katta farq yo'q: Facebook natijalarga qarab kimga ko'rsatishni o'zi o'rganadi"}, {"id": "c", "text": "Faqat ingliz tilini tanlash kerak"}, {"id": "d", "text": "Rus tilini tanlash reklamani 2 baravar arzonlashtiradi"}], "correct_option_id": "b", "explanation": "Algoritm lid qoldirgan odamlarni o'rganib, o'xshash odamlarni o'zi topadi."}, {"id": "q12", "prompt": "Advantage+ joylashuvlarida byudjet qanday taqsimlanadi?", "options": [{"id": "a", "text": "Byudjet har doim teng ikkiga bo'linadi"}, {"id": "b", "text": "Byudjet faqat Audience Network'ka sarflanadi"}, {"id": "c", "text": "Byudjet faqat Facebook'ga sarflanadi"}, {"id": "d", "text": "Facebook qaysi platformada natija arzonroq bo'lsa, byudjetni o'sha yerga ko'proq yo'naltiradi"}], "correct_option_id": "d", "explanation": "Misol: Instagram'da lid 2 baravar arzon chiqsa, pulning ko'p qismi Instagram'ga sarflanadi."}, {"id": "q13", "prompt": "Qurilmalar (Devices) sozlamalarida nimani tanlash mumkin?", "options": [{"id": "a", "text": "Faqat telefon raqam operatorini"}, {"id": "b", "text": "Telefon yoki kompyuter, Android yoki iOS, hatto qurilma turlari va tizim versiyalarini"}, {"id": "c", "text": "Faqat ekran rangini"}, {"id": "d", "text": "Faqat internet tezligini"}], "correct_option_id": "b", "explanation": "Masalan, faqat iOS uchun ilova bo'lsa, reklamani faqat iPhone egalariga ko'rsatish mumkin."}, {"id": "q14", "prompt": "Auditoriyani qurilma bo'yicha toraytirsangiz (masalan, faqat iPhone), nima bo'ladi?", "options": [{"id": "a", "text": "Auditoriya kattalashadi"}, {"id": "b", "text": "Hech narsa o'zgarmaydi"}, {"id": "c", "text": "Auditoriya kichrayadi va reklama odatda qimmatlashadi"}, {"id": "d", "text": "Reklama bepul bo'ladi"}], "correct_option_id": "c", "explanation": "Misolda 6 million kishilik auditoriya iPhone tanlanganda ancha kamaydi."}, {"id": "q15", "prompt": "Nega reklamaga bir nechta asosiy matn (Primary text) varianti yozish foydali?", "options": [{"id": "a", "text": "Facebook kamida 5 ta matn talab qiladi"}, {"id": "b", "text": "Hamma variantlar bir vaqtda bitta reklamada chiqadi"}, {"id": "c", "text": "Facebook ularni sinab, ko'proq e'tibor tortgan variantni ko'proq ko'rsatadi"}, {"id": "d", "text": "Matn ko'p bo'lsa, reklama bepul bo'ladi"}], "correct_option_id": "c", "explanation": "Bitta matn bilan 1 ta imkoniyat, 5 ta matn bilan 5 ta imkoniyat bor."}]$json$::jsonb, true)
on conflict (id) do update set title = excluded.title, questions = excluded.questions, section = excluded.section, section_order = excluded.section_order, lesson_order = excluded.lesson_order;

insert into public.tests(id, section, section_order, lesson_order, title, questions, published) values (
'5-5', '5. Reklama kampaniyalari', 5, 5, '5. Karusel format', $json$[{"id": "q1", "prompt": "Karusel (Carousel) formati nima?", "options": [{"id": "a", "text": "Faqat stories uchun video"}, {"id": "b", "text": "Faqat matnli reklama"}, {"id": "c", "text": "Bitta reklamada bir nechta rasm yoki video kartalar bo'ladi va ular yonga suriladi"}, {"id": "d", "text": "Bitta rasm yoki bitta video"}], "correct_option_id": "c", "explanation": "Odam kartalarni barmog'i bilan surib, birin-ketin ko'radi."}, {"id": "q2", "prompt": "Karuselda ko'pi bilan nechta karta (rasm yoki video) qo'yish mumkin?", "options": [{"id": "a", "text": "10 ta"}, {"id": "b", "text": "5 ta"}, {"id": "c", "text": "50 ta"}, {"id": "d", "text": "3 ta"}], "correct_option_id": "a", "explanation": "Ustoz 5 ta rasm yukladi va 5 ta karta hosil bo'ldi."}, {"id": "q3", "prompt": "Karuselga eng kamida nechta karta kerak?", "options": [{"id": "a", "text": "10 ta"}, {"id": "b", "text": "2 ta"}, {"id": "c", "text": "1 ta"}, {"id": "d", "text": "5 ta"}], "correct_option_id": "b", "explanation": "Bitta karta bilan karusel bo'lmaydi, bu oddiy bitta rasmli reklama bo'ladi."}, {"id": "q4", "prompt": "Karuseldagi rasmlar o'lchami haqida ustoz nima dedi?", "options": [{"id": "a", "text": "Har bir karta har xil o'lchamda bo'lishi kerak"}, {"id": "b", "text": "O'lcham ahamiyatsiz"}, {"id": "c", "text": "Faqat birinchi karta kvadrat bo'lishi kerak"}, {"id": "d", "text": "Hamma kartalar bir xil o'lchamda bo'lishi kerak, aks holda reklama xunuk ko'rinadi"}], "correct_option_id": "d", "explanation": "Bir xil o'lcham reklamani tartibli va chiroyli ko'rsatadi."}, {"id": "q5", "prompt": "Karuselni qachon ishlatgan ma'qul?", "options": [{"id": "a", "text": "Faqat bitta rasmni ko'rsatish kerak bo'lganda"}, {"id": "b", "text": "Faqat qo'ng'iroq olish kerak bo'lganda"}, {"id": "c", "text": "Faqat matn yozish kerak bo'lganda"}, {"id": "d", "text": "Bitta mahsulotning bir nechta funksiyasini yoki bir nechta mahsulotni ko'rsatish kerak bo'lganda"}], "correct_option_id": "d", "explanation": "Masalan, blenderning bir kartada bir funksiyasi, keyingisida boshqa funksiyasi ko'rsatiladi."}, {"id": "q6", "prompt": "Karuselda har bir kartaga alohida nima yozish mumkin?", "options": [{"id": "a", "text": "Alohida byudjet"}, {"id": "b", "text": "Alohida auditoriya"}, {"id": "c", "text": "Alohida reklama maqsadi"}, {"id": "d", "text": "Alohida sarlavha (Headline), tavsif va havola"}], "correct_option_id": "d", "explanation": "Masalan, mebel do'koni har bir kartadagi mahsulotni saytdagi o'sha mahsulot sahifasiga ulaydi."}, {"id": "q7", "prompt": "Karuseldagi asosiy matn (Primary text) haqida qaysi gap to'g'ri?", "options": [{"id": "a", "text": "Karuselda asosiy matn bo'lmaydi"}, {"id": "b", "text": "Asosiy matn hamma kartalar uchun bitta va umumiy bo'ladi"}, {"id": "c", "text": "Asosiy matn faqat oxirgi kartada chiqadi"}, {"id": "d", "text": "Har bir kartada alohida asosiy matn bo'ladi"}], "correct_option_id": "b", "explanation": "Sarlavhalar har bir kartada alohida, asosiy matn esa hamma kartalar uchun umumiy."}, {"id": "q8", "prompt": "Mebel do'koni misolida kreslo kartasi bosilganda odam qayerga o'tishi kerak?", "options": [{"id": "a", "text": "Saytning bosh sahifasiga"}, {"id": "b", "text": "Hech qayerga, karta bosilmaydi"}, {"id": "c", "text": "Saytdagi aynan o'sha kreslo sahifasiga"}, {"id": "d", "text": "Instagram profilga"}], "correct_option_id": "c", "explanation": "Odam qiziqqan mahsulotini qidirib yurmasligi uchun havola aynan o'sha mahsulotga olib borishi kerak."}]$json$::jsonb, true)
on conflict (id) do update set title = excluded.title, questions = excluded.questions, section = excluded.section, section_order = excluded.section_order, lesson_order = excluded.lesson_order;

insert into public.tests(id, section, section_order, lesson_order, title, questions, published) values (
'5-6', '5. Reklama kampaniyalari', 5, 6, '6. Trafik kampaniyasi', $json$[{"id": "q1", "prompt": "Trafik kampaniyasining maqsadi nima?", "options": [{"id": "a", "text": "Ilova o'rnatishlarini ko'paytirish"}, {"id": "b", "text": "Odamlarni siz tanlagan manzilga ko'proq olib borish"}, {"id": "c", "text": "Sotuvni pixel orqali hisoblash"}, {"id": "d", "text": "Telefon raqam yig'ish"}], "correct_option_id": "b", "explanation": "Manzil sayt, ilova, Instagram profil yoki messenjer bo'lishi mumkin."}, {"id": "q2", "prompt": "Trafikni qaysi manzillarga yo'naltirish mumkin?", "options": [{"id": "a", "text": "Faqat saytga"}, {"id": "b", "text": "Faqat telefon qo'ng'iroqlariga"}, {"id": "c", "text": "Faqat Instagram profilga"}, {"id": "d", "text": "Sayt, ilova, Messenger/Instagram/WhatsApp, Instagram profil va qo'ng'iroqlar"}], "correct_option_id": "d", "explanation": "Ustoz bu darsda saytni tanladi."}, {"id": "q3", "prompt": "Nega ustoz trafikni ilovaga yo'naltira olmadi?", "options": [{"id": "a", "text": "Ilovaga trafik bepul"}, {"id": "b", "text": "Uning Business Manager'iga ilova ulanmagan"}, {"id": "c", "text": "Bu variant faqat iPhone'da ishlaydi"}, {"id": "d", "text": "Ilova reklamasi taqiqlangan"}], "correct_option_id": "b", "explanation": "Ilovaga trafik yuborish uchun avval ilovani BMga ulash kerak."}, {"id": "q4", "prompt": "Instagram obunachilarni ko'paytirmoqchi bo'lsangiz, trafikni qayerga yo'naltirasiz?", "options": [{"id": "a", "text": "Telefon qo'ng'irog'iga"}, {"id": "b", "text": "Ilovaga"}, {"id": "c", "text": "Saytga"}, {"id": "d", "text": "Instagram profilga"}], "correct_option_id": "d", "explanation": "Reklama bosilganda odam to'g'ridan-to'g'ri Instagram profilingiz ochiladi."}, {"id": "q5", "prompt": "«Максимальное число просмотров целевой страницы» (Maximize landing page views) nimani bildiradi?", "options": [{"id": "a", "text": "Faqat layk bosadiganlarni"}, {"id": "b", "text": "Facebook tugmani bosib, saytni haqiqatan ochib ko'radigan odamlarni qidiradi"}, {"id": "c", "text": "Tugmani ko'p bosadiganlarni, sayt ochilmasa ham"}, {"id": "d", "text": "Faqat videoni ko'radiganlarni"}], "correct_option_id": "b", "explanation": "Bu odamlar sayt yuklanguncha kutib, sahifani ko'radi."}, {"id": "q6", "prompt": "Nega «Максимальное число кликов по ссылке» (Maximize link clicks) tanlansa, saytga kirganlar kamroq bo'lishi mumkin?", "options": [{"id": "a", "text": "Chunki bu variant saytni bloklaydi"}, {"id": "b", "text": "Odam tugmani bosgan bilan internet sekinligi yoki sayt yuklanguncha chiqib ketgani uchun sahifani ko'rmasligi mumkin"}, {"id": "c", "text": "Chunki kliklar faqat Facebook'da hisoblanadi"}, {"id": "d", "text": "Chunki kliklar pulsiz"}], "correct_option_id": "b", "explanation": "Shuning uchun ustoz saytga trafik uchun «просмотры целевой страницы»ni tanladi."}, {"id": "q7", "prompt": "Kuniga 5 dollar byudjet qo'yilganda Facebook ko'rsatgan natijalar haqida ustoz nima dedi?", "options": [{"id": "a", "text": "Bu raqobatchilarning natijasi"}, {"id": "b", "text": "Bu o'tgan oyning natijasi"}, {"id": "c", "text": "Bu kafolatlangan natija"}, {"id": "d", "text": "Bu taxminiy raqamlar, aniq emas"}], "correct_option_id": "d", "explanation": "Facebook bergan bashorat natijaning taxminiy chegarasini ko'rsatadi."}, {"id": "q8", "prompt": "Nega rasmni ham to'liq ekranli 9:16 formatida tayyorlash kerak?", "options": [{"id": "a", "text": "Facebook boshqa o'lchamni qabul qilmaydi"}, {"id": "b", "text": "Reels va stories'da reklama to'liq ekranda chiroyli chiqishi uchun"}, {"id": "c", "text": "9:16 reklamani bepul qiladi"}, {"id": "d", "text": "9:16 faqat kompyuterda ishlaydi"}], "correct_option_id": "b", "explanation": "Har bir joylashuvda rasm qanday chiqishini oldindan ko'rish (Предпросмотр) orqali tekshirish mumkin."}, {"id": "q9", "prompt": "Ustoz «Оптимизация текста» (Text optimization) funksiyasini nega o'chirdi?", "options": [{"id": "a", "text": "Facebook sarlavha bilan asosiy matnning o'rnini almashtirib yuboradi va reklama siz xohlagandek chiqmaydi"}, {"id": "b", "text": "Bu funksiya faqat Instagram'da bor"}, {"id": "c", "text": "Bu funksiya reklamani bloklaydi"}, {"id": "d", "text": "Bu funksiya pullik"}], "correct_option_id": "a", "explanation": "Ba'zi odamlarga sarlavha tepada, asosiy matn pastda chiqib qolishi mumkin. Shuning uchun u o'chirildi."}, {"id": "q10", "prompt": "Trafik reklamasidagi tugma (Call to action) uchun qaysi variantlar ko'rsatildi?", "options": [{"id": "a", "text": "«Нравится», «Комментировать», «Поделиться»"}, {"id": "b", "text": "Faqat «Позвонить»"}, {"id": "c", "text": "«Удалить», «Скрыть», «Пожаловаться»"}, {"id": "d", "text": "«Подробнее» (Learn more), «Заказать» (Order now), «Зарегистрироваться» (Sign up), «В магазин» (Shop now)"}], "correct_option_id": "d", "explanation": "Tugma reklamaning maqsadiga mos tanlanadi: masalan, ro'yxatdan o'tishga taklif bo'lsa «Зарегистрироваться»."}, {"id": "q11", "prompt": "Brauzer qo'shimchalari (Browser add-ons) bo'limidagi qo'ng'iroq tugmasi nima qiladi?", "options": [{"id": "a", "text": "Sayt reklamadan ochilganda tepada qo'ng'iroq qilish tugmasi chiqadi va odam bir bosishda qo'ng'iroq qila oladi"}, {"id": "b", "text": "Saytni Facebook'dan o'chiradi"}, {"id": "c", "text": "Pixelni o'chiradi"}, {"id": "d", "text": "Saytga to'lov tizimini qo'shadi"}], "correct_option_id": "a", "explanation": "Facebook saytingiz ustiga telefon raqamli tugmani o'zi qo'shadi."}, {"id": "q12", "prompt": "Reklama yaratishning oxirida pixel nima uchun tanlanadi?", "options": [{"id": "a", "text": "Reklama rasmini chiroyli qilish uchun"}, {"id": "b", "text": "Instagram'ni ulash uchun"}, {"id": "c", "text": "Reklamadan saytga kirganlar qanday harakat qilganini kuzatish uchun"}, {"id": "d", "text": "Byudjetni kamaytirish uchun"}], "correct_option_id": "c", "explanation": "Pixel saytdagi lid, sotuv va boshqa eventlarni reklama bilan bog'lab ko'rsatadi."}]$json$::jsonb, true)
on conflict (id) do update set title = excluded.title, questions = excluded.questions, section = excluded.section, section_order = excluded.section_order, lesson_order = excluded.lesson_order;

insert into public.tests(id, section, section_order, lesson_order, title, questions, published) values (
'5-7', '5. Reklama kampaniyalari', 5, 7, '7. Вовлеченность kampaniyasi', $json$[{"id": "q1", "prompt": "«Вовлеченность» (Engagement) kampaniyasining vazifasi nima?", "options": [{"id": "a", "text": "Odamlarning reklama bilan o'zaro aloqasini ko'paytirish: layk, izoh, xabar yozish, video ko'rish"}, {"id": "b", "text": "Faqat ilova o'rnatishlarini ko'paytirish"}, {"id": "c", "text": "Faqat saytga trafik olib kelish"}, {"id": "d", "text": "Faqat sotuvlarni hisoblash"}], "correct_option_id": "a", "explanation": "Bu maqsadda Facebook odamlar reklama bilan qandaydir harakat qilishini kutadi."}, {"id": "q2", "prompt": "«Вовлеченность» kampaniyasida o'zaro aloqa qayerda bo'lishi mumkin?", "options": [{"id": "a", "text": "Faqat saytda"}, {"id": "b", "text": "Faqat telefon qo'ng'iroqlarida"}, {"id": "c", "text": "Messenjerlarda (Messenger, Instagram, WhatsApp), reklamaning o'zida, qo'ng'iroqlarda, saytda yoki sahifada"}, {"id": "d", "text": "Faqat ilovada"}], "correct_option_id": "c", "explanation": "Ustoz bu ro'yxatni birma-bir ko'rsatib chiqdi."}, {"id": "q3", "prompt": "Вовлеченность kampaniyasida «Сайт» (Website) tanlansa, nima qo'shimcha tanlanadi?", "options": [{"id": "a", "text": "Telefon raqam"}, {"id": "b", "text": "Saytdagi qaysi harakatni kutayotganingiz, ya'ni event (masalan, «Контакт»)"}, {"id": "c", "text": "Ilovaning nomi"}, {"id": "d", "text": "Instagram profili"}], "correct_option_id": "b", "explanation": "Facebook shu eventni bajaradigan odamlarni qidiradi."}, {"id": "q4", "prompt": "Ustoz «Вовлеченность» kampaniyasidan asosan nima uchun foydalanadi?", "options": [{"id": "a", "text": "Lid yig'ish uchun"}, {"id": "b", "text": "Videosini ko'proq odam ko'rishi uchun"}, {"id": "c", "text": "Ilova reklamasi uchun"}, {"id": "d", "text": "Sotuv uchun"}], "correct_option_id": "b", "explanation": "Videoni ko'p ko'rishsa, ko'rganlardan keyin alohida auditoriya yasash mumkin."}, {"id": "q5", "prompt": "Nega videoni ko'rganlarni keyinchalik auditoriya qilib olish foydali?", "options": [{"id": "a", "text": "Ular avtomatik mijozga aylanadi"}, {"id": "b", "text": "Videoni, masalan, yarmigacha ko'rgan odam shu mavzuga qiziqqan. Unga keyin boshqa reklamani ko'rsatish mumkin"}, {"id": "c", "text": "Facebook ularni bloklaydi"}, {"id": "d", "text": "Ular reklamani bepul ko'radi"}], "correct_option_id": "b", "explanation": "Bu keyingi darslarda o'tiladigan retarget usuli."}, {"id": "q6", "prompt": "Videoni ko'rish maqsadida qaysi natija variantlari bor?", "options": [{"id": "a", "text": "Faqat layklar soni"}, {"id": "b", "text": "Faqat izohlar soni"}, {"id": "c", "text": "ThruPlay (15 soniya yoki oxirigacha) va 2 soniyalik uzluksiz ko'rish"}, {"id": "d", "text": "Faqat saytga kirishlar soni"}], "correct_option_id": "c", "explanation": "ThruPlay videoni uzoqroq ko'radiganlarni topadi."}, {"id": "q7", "prompt": "Video ko'rish maqsadidagi reklamada nega rasm emas, video qo'yildi?", "options": [{"id": "a", "text": "Maqsad videoni ko'proq odamga ko'rsatish, rasm bilan bu maqsadga erishib bo'lmaydi"}, {"id": "b", "text": "Rasm Instagram'da chiqmaydi"}, {"id": "c", "text": "Rasm qo'yish taqiqlangan"}, {"id": "d", "text": "Video arzonroq"}], "correct_option_id": "a", "explanation": "Reklama guruhida maqsad video ko'rish bo'lgani uchun kreativ ham video bo'lishi shart."}, {"id": "q8", "prompt": "Video ko'rish reklamasida tugma (Call to action) haqida ustoz nima dedi?", "options": [{"id": "a", "text": "Tugma albatta bo'lishi shart"}, {"id": "b", "text": "Tugma reklamani ikki baravar arzonlashtiradi"}, {"id": "c", "text": "Odatiy holatda tugma yo'q, chunki maqsad videoni ko'rsatish. Xohlasangiz qo'shish mumkin"}, {"id": "d", "text": "Tugmani qo'shib bo'lmaydi"}], "correct_option_id": "c", "explanation": "Tugma qo'shilsa ham, Facebook baribir videoni ko'radiganlarni qidiradi."}]$json$::jsonb, true)
on conflict (id) do update set title = excluded.title, questions = excluded.questions, section = excluded.section, section_order = excluded.section_order, lesson_order = excluded.lesson_order;

insert into public.tests(id, section, section_order, lesson_order, title, questions, published) values (
'5-8', '5. Reklama kampaniyalari', 5, 8, '8. LID reklamasi (moment forma)', $json$[{"id": "q1", "prompt": "Lid kampaniyasida lidni qayerdan olish mumkin?", "options": [{"id": "a", "text": "Faqat telefon qo'ng'irog'idan"}, {"id": "b", "text": "Faqat pochta orqali"}, {"id": "c", "text": "Faqat Telegram'dan"}, {"id": "d", "text": "Saytdan yoki «Моментальная форма» (Instant form) orqali"}], "correct_option_id": "d", "explanation": "Ustoz shaxsan saytni yoqtiradi, lekin bu darsda moment formani ko'rsatdi."}, {"id": "q2", "prompt": "Moment forma qayerda ochiladi?", "options": [{"id": "a", "text": "Faqat kompyuterda alohida saytda"}, {"id": "b", "text": "Mijozning pochtasida"}, {"id": "c", "text": "Reklama tugmasi bosilganda Instagram yoki Facebook'ning o'zida, saytga o'tmasdan"}, {"id": "d", "text": "Telegram botda"}], "correct_option_id": "c", "explanation": "Odam ilovadan chiqmasdan ismi va telefon raqamini yozib, lid qoldiradi."}, {"id": "q3", "prompt": "Ustoz nega shaxsan saytdan lid olishni yoqtiradi?", "options": [{"id": "a", "text": "Saytda lidlar ko'proq va arzonroq"}, {"id": "b", "text": "Sayt bepul"}, {"id": "c", "text": "Moment forma taqiqlangan"}, {"id": "d", "text": "Odam saytda mahsulot haqida ma'lumot olib, keyin lid qoldiradi. Bunday lidlar sifatliroq"}], "correct_option_id": "d", "explanation": "Moment formada lid ko'p va arzon bo'ladi, lekin sifati pastroq bo'lishi mumkin."}, {"id": "q4", "prompt": "Moment formadan foydalanish uchun avval nima qilish kerak?", "options": [{"id": "a", "text": "Facebook'ning lid reklamasi shartlarini (Terms) qabul qilish"}, {"id": "b", "text": "Yangi BM ochish"}, {"id": "c", "text": "Sayt sotib olish"}, {"id": "d", "text": "Pixel o'rnatish"}], "correct_option_id": "a", "explanation": "Shartlar bir marta qabul qilinadi, keyin forma yaratish mumkin."}, {"id": "q5", "prompt": "Nega moment formada pixel kerak emas?", "options": [{"id": "a", "text": "Pixel lidlarni o'chirib yuboradi"}, {"id": "b", "text": "Odam saytga o'tmaydi, lid Facebook'ning o'zida qoldiriladi"}, {"id": "c", "text": "Pixel faqat Instagram'da ishlaydi"}, {"id": "d", "text": "Pixel pullik"}], "correct_option_id": "b", "explanation": "Pixel saytdagi harakatlarni kuzatadi. Moment formada esa sayt yo'q."}, {"id": "q6", "prompt": "Formaga beriladigan nom kimga ko'rinadi?", "options": [{"id": "a", "text": "Hamma mijozlarga"}, {"id": "b", "text": "Faqat raqobatchilarga"}, {"id": "c", "text": "Faqat sizga, mijozga ko'rinmaydi. Keyin shu formani boshqa reklamalarda ham ishlatish mumkin"}, {"id": "d", "text": "Faqat Facebook adminlariga"}], "correct_option_id": "c", "explanation": "Nom keyin kerakli formani tez topish uchun beriladi."}, {"id": "q7", "prompt": "«Больше объема» (More volume) va «Более высокое намерение» (Higher intent) turlarining farqi nimada?", "options": [{"id": "a", "text": "Farqi yo'q"}, {"id": "b", "text": "Ikkinchisi faqat saytda ishlaydi"}, {"id": "c", "text": "Birinchisi ko'p va arzon lid beradi. Ikkinchisida odam ma'lumotlarini tekshirib, tasdiqlaydi, shuning uchun lidlar sifatliroq"}, {"id": "d", "text": "Birinchisi pullik, ikkinchisi bepul"}], "correct_option_id": "c", "explanation": "Higher intent'da yuborishdan oldin ma'lumotlarni tekshirish oynasi chiqadi."}, {"id": "q8", "prompt": "«Приветствие» (Intro) bo'limida nima ko'rsatiladi?", "options": [{"id": "a", "text": "Pixel kodi"}, {"id": "b", "text": "Forma ochilganda chiqadigan rasm, sarlavha va mahsulot haqida qisqa ma'lumot yoki foydalari ro'yxati"}, {"id": "c", "text": "Mijozning telefon raqami"}, {"id": "d", "text": "Reklama byudjeti"}], "correct_option_id": "b", "explanation": "Masalan, blender: zaryadda ishlaydi, 20 ta kokteyl tayyorlaydi."}, {"id": "q9", "prompt": "Formaga ustoz qaysi ma'lumotni so'raydigan qilib qo'ydi?", "options": [{"id": "a", "text": "Bank kartasi raqami"}, {"id": "b", "text": "Ism va telefon raqamni. Email olib tashlandi"}, {"id": "c", "text": "Faqat email"}, {"id": "d", "text": "Pasport ma'lumotlari"}], "correct_option_id": "b", "explanation": "O'zbekistonda mijoz bilan asosan telefon orqali bog'laniladi, shuning uchun email kerak emas."}, {"id": "q10", "prompt": "Formaga savollarni ko'paytirish lidlarga qanday ta'sir qiladi?", "options": [{"id": "a", "text": "Savollar soni ta'sir qilmaydi"}, {"id": "b", "text": "Savol ko'p bo'lsa, lid sifatliroq, lekin qimmatroq va kamroq bo'ladi. Savol kam bo'lsa, lid arzonroq va ko'proq bo'ladi"}, {"id": "c", "text": "Savol qo'shib bo'lmaydi"}, {"id": "d", "text": "Savol ko'p bo'lsa, lid arzonlashadi"}], "correct_option_id": "b", "explanation": "Masalan, uy-joy reklamasida «necha xonali uy kerak?» deb so'rash mumkin."}, {"id": "q11", "prompt": "Variantli savolga darsdagi misol qaysi?", "options": [{"id": "a", "text": "«Telefon raqamingiz?»"}, {"id": "b", "text": "«Ismingiz nima?»"}, {"id": "c", "text": "«Emailingiz?»"}, {"id": "d", "text": "«Necha xonali uy kerak?» — 1 xona, 2 xona, 3 xona"}], "correct_option_id": "d", "explanation": "Variantli savollar mijozni oldindan saralash uchun kerak."}, {"id": "q12", "prompt": "«Политика конфиденциальности» (Privacy policy) bo'limiga nima qo'yiladi?", "options": [{"id": "a", "text": "Reklama rasmi"}, {"id": "b", "text": "Kunlik byudjet"}, {"id": "c", "text": "Mijozning parol"}, {"id": "d", "text": "Kompaniyaning maxfiylik siyosati yozilgan sahifaning havolasi (masalan, saytdagi sahifa)"}], "correct_option_id": "d", "explanation": "Bu majburiy maydon: odam ma'lumotlari qanday ishlatilishini bilishi kerak."}, {"id": "q13", "prompt": "«Экран завершения» (Completion screen) nima?", "options": [{"id": "a", "text": "Facebook'dan chiqish oynasi"}, {"id": "b", "text": "Byudjet tugagani haqidagi oyna"}, {"id": "c", "text": "Reklama to'xtagani haqidagi xabar"}, {"id": "d", "text": "Forma yuborilgandan keyin chiqadigan oyna: masalan, «menejerimiz siz bilan bog'lanadi» degan xabar va tugma"}], "correct_option_id": "d", "explanation": "Bu yerda saytga o'tish, qo'ng'iroq qilish yoki fayl yuklab olish tugmasini qo'yish mumkin."}, {"id": "q14", "prompt": "Ustozning aytishicha, nega mijozga «qo'ng'iroq qilish» tugmasini berish foydali?", "options": [{"id": "a", "text": "Mijoz boshqa hech narsa qila olmaydi"}, {"id": "b", "text": "Mijozning o'zi qo'ng'iroq qilsa, u xarid qilishga tayyorroq bo'ladi va suhbat osonroq kechadi"}, {"id": "c", "text": "Qo'ng'iroq bepul bo'ladi"}, {"id": "d", "text": "Facebook buni talab qiladi"}], "correct_option_id": "b", "explanation": "Siz qo'ng'iroq qilsangiz, mijoz sotuvga qarshi turadi. U o'zi qo'ng'iroq qilsa, psixologiya boshqacha."}, {"id": "q15", "prompt": "Moment formada rasm o'lchami haqida nima aytildi?", "options": [{"id": "a", "text": "Rasm umuman qo'yilmaydi"}, {"id": "b", "text": "Rasm formaga mos o'lchamda (gorizontal) bo'lishi kerak, aks holda yaxshi chiqmaydi"}, {"id": "c", "text": "Faqat vertikal video qo'yiladi"}, {"id": "d", "text": "Har qanday o'lcham bir xil chiqadi"}], "correct_option_id": "b", "explanation": "Ustozning rasmi formatga to'g'ri kelmagani uchun yaxshi chiqmadi."}]$json$::jsonb, true)
on conflict (id) do update set title = excluded.title, questions = excluded.questions, section = excluded.section, section_order = excluded.section_order, lesson_order = excluded.lesson_order;

insert into public.tests(id, section, section_order, lesson_order, title, questions, published) values (
'5-9', '5. Reklama kampaniyalari', 5, 9, '9. Lidlarni ko''chirish', $json$[{"id": "q1", "prompt": "Moment formadan kelgan lidlarni qayerdan ko'rish va yuklab olish mumkin?", "options": [{"id": "a", "text": "Instagram'dagi «Direct» bo'limidan"}, {"id": "b", "text": "Meta Business Suite > «Все инструменты» (All tools) > «Моментальные формы» (Instant forms)"}, {"id": "c", "text": "Gmail'dan"}, {"id": "d", "text": "Ads Manager'dagi «Счета» bo'limidan"}], "correct_option_id": "b", "explanation": "U yerda formasi bor sahifa tanlanadi va lidlar ko'rinadi."}, {"id": "q2", "prompt": "Lidlarni qaysi fayl formatlarida yuklab olish mumkin?", "options": [{"id": "a", "text": "PDF yoki DOC"}, {"id": "b", "text": "MP4 yoki MP3"}, {"id": "c", "text": "CSV yoki XLS"}, {"id": "d", "text": "PNG yoki JPG"}], "correct_option_id": "c", "explanation": "Faylni Excel'da ochib, telefon raqamlarni ko'rish mumkin."}, {"id": "q3", "prompt": "Lidlarni qo'lda yuklab olishdan tashqari ikkinchi yo'l qaysi?", "options": [{"id": "a", "text": "Lidlarni chop etish"}, {"id": "b", "text": "CRM tizimiga ulash: lidlar avtomatik CRMga tushadi"}, {"id": "c", "text": "Ikkinchi yo'l yo'q"}, {"id": "d", "text": "Lidlarni Instagram'ga post qilish"}], "correct_option_id": "b", "explanation": "Masalan, amoCRM yoki boshqa CRMga ulash mumkin."}, {"id": "q4", "prompt": "Ba'zi CRMlarni ulash uchun qaysi xizmatlardan foydalaniladi?", "options": [{"id": "a", "text": "Hech qanday xizmat kerak emas"}, {"id": "b", "text": "Faqat Gmail'dan"}, {"id": "c", "text": "Faqat Telegram botdan"}, {"id": "d", "text": "Zapier kabi pullik integratsiya xizmatlaridan"}], "correct_option_id": "d", "explanation": "Integrator Facebook bilan CRM o'rtasida ko'prik vazifasini bajaradi."}, {"id": "q5", "prompt": "amoCRM'ga Facebook lidlarini ulash uchun qayerga kiriladi?", "options": [{"id": "a", "text": "«Воронка» > «Настроить воронку» > «Источник» qismiga va Facebook formasi qo'shiladi"}, {"id": "b", "text": "«Почта» > «Входящие»"}, {"id": "c", "text": "«Задачи» > «Календарь»"}, {"id": "d", "text": "«Настройки профиля» > «Пароль»"}], "correct_option_id": "a", "explanation": "Akkaunt, sahifa va forma tanlanib saqlangach, lidlar avtomatik keladi."}, {"id": "q6", "prompt": "Lidlar CRMga ulangandan keyin nima qulaylik bo'ladi?", "options": [{"id": "a", "text": "Har bir yangi lid darhol CRMga tushadi va menejer yoki call-markaz u bilan tezda ishlay boshlaydi"}, {"id": "b", "text": "Reklama avtomatik to'xtaydi"}, {"id": "c", "text": "Lidlar bepul bo'ladi"}, {"id": "d", "text": "Lidlar Instagram'da chiqadi"}], "correct_option_id": "a", "explanation": "Lidni qo'lda yuklab o'tirish shart emas, u o'zi tushadi."}]$json$::jsonb, true)
on conflict (id) do update set title = excluded.title, questions = excluded.questions, section = excluded.section, section_order = excluded.section_order, lesson_order = excluded.lesson_order;

insert into public.tests(id, section, section_order, lesson_order, title, questions, published) values (
'5-10', '5. Reklama kampaniyalari', 5, 10, '10. Purchase maqsadi', $json$[{"id": "q1", "prompt": "Sotuvlar uchun reklama yaratishda qaysi maqsad tanlanadi?", "options": [{"id": "a", "text": "«Узнаваемость» (Awareness)"}, {"id": "b", "text": "«Лиды» (Leads)"}, {"id": "c", "text": "«Продажи» (Sales)"}, {"id": "d", "text": "«Трафик» (Traffic)"}], "correct_option_id": "c", "explanation": "Keyin konversiya joyi sifatida sayt, event sifatida esa «Покупка» (Purchase) tanlanadi."}, {"id": "q2", "prompt": "Sotuv maqsadida reklama qaysi eventga moslashtiriladi?", "options": [{"id": "a", "text": "PageView"}, {"id": "b", "text": "«Покупка» (Purchase)"}, {"id": "c", "text": "«Контакт» (Contact)"}, {"id": "d", "text": "«Лид» (Lead)"}], "correct_option_id": "b", "explanation": "Facebook Purchase eventini bajarishi ehtimoli yuqori bo'lgan odamlarni qidiradi."}, {"id": "q3", "prompt": "Purchase maqsadida reklama to'g'ri ishlashi uchun saytda nima bo'lishi shart?", "options": [{"id": "a", "text": "Ilova"}, {"id": "b", "text": "Purchase eventi o'rnatilgan pixel"}, {"id": "c", "text": "Instagram profil"}, {"id": "d", "text": "Telegram kanal"}], "correct_option_id": "b", "explanation": "Event o'rnatilmagan bo'lsa, Facebook kimlar sotib olganini bilmaydi va reklamani moslashtira olmaydi."}, {"id": "q4", "prompt": "Ustozning aytishicha, bitta sotuvning narxi haqida qaysi gap to'g'ri?", "options": [{"id": "a", "text": "Mahsulot qimmat bo'lsa, bitta sotuv uchun ko'p pul (masalan, 120 yoki 200 dollar) sarflanishi mumkin. Arzon mahsulotda narx boshqacha bo'ladi"}, {"id": "b", "text": "Narx faqat byudjetga bog'liq, mahsulotga emas"}, {"id": "c", "text": "Har bir sotuv doim 1 dollar turadi"}, {"id": "d", "text": "Sotuvlar bepul keladi"}], "correct_option_id": "a", "explanation": "Facebook ko'rsatgan raqamlar taxminiy, haqiqiy narx mahsulot va bozorga bog'liq."}, {"id": "q5", "prompt": "Purchase reklamasi ishga tushgandan keyin pixel orqali nimani ko'rish mumkin?", "options": [{"id": "a", "text": "Qancha pul sarflangani, nechta sotuv bo'lgani va sotuvlar summasini"}, {"id": "b", "text": "Hech narsani"}, {"id": "c", "text": "Faqat obunachilar sonini"}, {"id": "d", "text": "Faqat layklar sonini"}], "correct_option_id": "a", "explanation": "Shuning uchun pixel doim to'g'ri ishlab turishi kerak."}]$json$::jsonb, true)
on conflict (id) do update set title = excluded.title, questions = excluded.questions, section = excluded.section, section_order = excluded.section_order, lesson_order = excluded.lesson_order;

insert into public.tests(id, section, section_order, lesson_order, title, questions, published) values (
'5-1r', '5. Reklama kampaniyalari', 5, 1, '1. Reklama turlari — rasmli 🖼', $json$[{"id": "q1", "image": "images/5-1/q1.jpg", "keep_order": true, "prompt": "Business Manager'dagi «Все инструменты» (All tools) menyusi ochiq. Reklama yaratish uchun Ads Manager'ni ochmoqchisiz. Qaysi belgini bosasiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "d", "explanation": "D: «Ads Manager». Ads Manager reklama kampaniyalari yaratiladigan joy. A: «Отчеты по рекламе» (Ads reporting), B: «Настройки компании» (Business settings), C: «Events Manager»."}, {"id": "q2", "image": "images/5-1/q2.jpg", "keep_order": true, "prompt": "Reklama orqali telefon raqam (lid) yig'moqchisiz. Qaysi maqsadni tanlaysiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "d", "explanation": "D: «Лиды» (Leads). Lid — mijozning ismi va telefon raqami. Uni yig'ish uchun «Лиды» maqsadi tanlanadi. A: «Продажи» (Sales), B: «Трафик» (Traffic), C: «Вовлеченность» (Engagement)."}, {"id": "q3", "image": "images/5-1/q3.jpg", "prompt": "Kampaniya yaratish oynasining tepasida shu sariq ogohlantirish chiqdi. U nimani bildiradi?", "options": [{"id": "a", "text": "Byudjet tugab qolgan"}, {"id": "b", "text": "Reklama akkaunti butunlay bloklangan"}, {"id": "c", "text": "Kampaniya muvaffaqiyatli yaratildi"}, {"id": "d", "text": "«Требуется информация об аккаунте»: reklama berishdan oldin akkaunt haqidagi ba'zi ma'lumotlarni to'ldirish va tasdiqlash kerak"}], "correct_option_id": "d", "explanation": "«Перейти к обзору аккаунта» tugmasi orqali kerakli ma'lumotlar to'ldiriladi. Ustoz sahifaga kirish ruxsatini berib, bu muammoni hal qildi."}, {"id": "q4", "image": "images/5-1/q4.jpg", "keep_order": true, "prompt": "Sahifaga odam qo'shish oynasi. Shu odam sahifa nomidan reklama yarata olishi uchun qaysi kalitni yoqasiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "d", "explanation": "D: «Реклама» (Ads). «Реклама» kaliti sahifa uchun reklama yaratish, tahrirlash va o'chirish huquqini beradi. Keyin «Назначить» bosiladi. A: «Контент» (Content), B: «Сообщения и звонки» (Messages and calls), C: «Статистика» (Insights)."}, {"id": "q5", "image": "images/5-1/q5.jpg", "prompt": "Rasmda qaysi maqsad tanlangan va u nima uchun ishlatiladi?", "options": [{"id": "a", "text": "«Продажи» (Sales): saytdan sotuv qilish uchun"}, {"id": "b", "text": "«Продвижение приложения» (App promotion): ilovani yuklab olib, o'rnatadigan odamlarni topish uchun"}, {"id": "c", "text": "«Лиды» (Leads): telefon raqam yig'ish uchun"}, {"id": "d", "text": "«Узнаваемость» (Awareness): brendni tanitish uchun"}], "correct_option_id": "b", "explanation": "O'ngdagi tavsifda ham yozilgan: «Установки приложения» (App installs) va «События в приложении» (App events). Ustoz bu maqsadni deyarli ishlatmaydi."}]$json$::jsonb, true)
on conflict (id) do update set title = excluded.title, questions = excluded.questions, section = excluded.section, section_order = excluded.section_order, lesson_order = excluded.lesson_order;

insert into public.tests(id, section, section_order, lesson_order, title, questions, published) values (
'5-2r', '5. Reklama kampaniyalari', 5, 2, '2. Kampaniya bosqichlari — rasmli 🖼', $json$[{"id": "q1", "image": "images/5-2/q1.jpg", "keep_order": true, "prompt": "Ads Manager ochiq. Kampaniya ichidagi reklama guruhlarini (Ad sets) ko'rish uchun qaysi bo'limni bosasiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "a", "explanation": "A: «Группы объявлений» (Ad sets). Ads Manager'da uchta bo'lim bor: kampaniyalar, reklama guruhlari va reklamalar. B: «Кампании» (Campaigns), C: «Создать» (Create), D: «Объявления» (Ads)."}, {"id": "q2", "image": "images/5-2/q2.jpg", "keep_order": true, "prompt": "Ustoz chizgan sxema. Qaysi blok reklama guruhini («Группа объявлений», Ad set) bildiradi?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "a", "explanation": "A: o'rtadagi yashil blok «Группа объявлений 2». Kampaniya ichida bir nechta reklama guruhi, har bir guruh ichida esa bir nechta reklama bo'ladi. B: sariq «Мақсад» eslatmasi, C: sariq «Кампания» bloki, D: ko'k «Объявление 1» bloki."}, {"id": "q3", "image": "images/5-2/q3.jpg", "prompt": "Sxemadagi yashil eslatmada «Бюджет, Таргетинг, Жойлашув» deb yozilgan. Bular qaysi bosqichda sozlanadi?", "options": [{"id": "a", "text": "«Объявление» (Ad) bosqichida"}, {"id": "b", "text": "Business Manager sozlamalarida"}, {"id": "c", "text": "«Группа объявлений» (Ad set) bosqichida"}, {"id": "d", "text": "«Кампания» (Campaign) bosqichida"}], "correct_option_id": "c", "explanation": "Kampaniyada maqsad, reklama guruhida byudjet, targeting va joylashuv, reklamada esa video/rasm, matn va sayt havolasi sozlanadi."}, {"id": "q4", "image": "images/5-2/q4.jpg", "prompt": "Kampaniya yaratishda shu oyna chiqdi. Hamma sozlamalarni o'zingiz tanlash uchun qaysi variant kerak?", "options": [{"id": "a", "text": "«Recommended settings» (tavsiya qilingan sozlamalar)"}, {"id": "b", "text": "«Назад» (orqaga) tugmasi"}, {"id": "c", "text": "«Простой интерфейс» (oddiy interfeys)"}, {"id": "d", "text": "«Ручная настройка» (Manual setup): «Кампания с целью «лиды», созданная вручную»"}], "correct_option_id": "d", "explanation": "Ustoz kampaniyani noldan, sozlamalarni o'zi tanlab yaratdi."}, {"id": "q5", "image": "images/5-2/q5.jpg", "keep_order": true, "prompt": "Chap tomondagi ro'yxatda kampaniya tuzilishi ko'rinib turibdi. Qaysi qator reklama guruhini (Ad set) bildiradi?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "d", "explanation": "D: «Новая группа объявлений…». Tepada kampaniya, uning ostida reklama guruhi, eng pastda reklama turadi. A: «Создать» (Create), B: «Новая кампания…», C: «Новое объявление…»."}, {"id": "q6", "image": "images/5-2/q6.jpg", "keep_order": true, "prompt": "Kampaniya qatori ustiga sichqoncha olib borildi. Kampaniya sozlamalarini o'zgartirish uchun qaysi tugmani bosasiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "d", "explanation": "D: «Изменить» (Edit). Kampaniya, guruh va reklamaning har birida alohida «Изменить» tugmasi bor. A: «Прикрепить» (Pin), B: «Удалить» (Delete) belgisi, C: «Дублировать» (Duplicate)."}, {"id": "q7", "image": "images/5-2/q7.jpg", "keep_order": true, "prompt": "Reklama guruhi sozlamalari. Byudjet turini (kunlik yoki umumiy) qayerda tanlaysiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "d", "explanation": "D: «Дневной бюджет» (Daily budget) ochiladigan ro'yxati. Ro'yxatdan «Дневной бюджет» yoki «Бюджет на весь срок действия» tanlanadi, yonidagi maydonga summa yoziladi. A: «Динамические креативы» kaliti, B: «Дата начала» (Start date), C: «Установить дату окончания» (Set end date)."}, {"id": "q8", "image": "images/5-2/q8.jpg", "keep_order": true, "prompt": "Auditoriya bo'limi. Yoshni 25–30 qilib o'zgartirish uchun qaysi tugmani bosasiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "c", "explanation": "C: «Редактировать» (Edit). Joylashuv, yosh, jins va qiziqishlar «Редактировать» bosilgandan keyin o'zgartiriladi. A: «Исключить» (Exclude), B: «Сохранить аудиторию» (Save audience), D: «Использовать аудиторию Advantage+»."}, {"id": "q9", "image": "images/5-2/q9.jpg", "keep_order": true, "prompt": "Joylashuvlar ro'yxati. Reklamani stories va Reels'da ko'rsatish uchun qaysi band belgilangan bo'lishi kerak?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "c", "explanation": "C: «Истории и видео Reels» (Stories and Reels). Reklama qayerda chiqishi reklama guruhi bosqichida belgilanadi. A: «Приложения и сайты» (Apps and sites), B: «Результаты поиска» (Search results), D: «Ленты» (Feeds)."}, {"id": "q10", "image": "images/5-2/q10.jpg", "keep_order": true, "prompt": "Reklama (Ad) bosqichi. Bir nechta rasmni yonga suriladigan qilib ko'rsatmoqchisiz. Qaysi formatni tanlaysiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "c", "explanation": "C: «Кольцевая галерея» (Carousel). Karusel 2 va undan ko'p rasm yoki videoni yonga surib ko'rish imkonini beradi. A: «Одно изображение или видео» (Single image or video), B: «Создать рекламу» ro'yxati, D: «Объявления в рекламном блоке…» belgisi."}, {"id": "q11", "image": "images/5-2/q11.jpg", "keep_order": true, "prompt": "Reklama guruhi dublikat qilinmoqda. Nusxa o'sha kampaniyaning ichida qolishi uchun qaysi variant tanlanadi?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "a", "explanation": "A: «Оригинальная кампания» (Original campaign). Ustoz guruhni shu kampaniya ichida nusxaladi, keyin nusxaning auditoriya va byudjetini o'zgartirdi. B: «Существующая кампания» (Existing campaign), C: «Новое A/B-тестирование» (New A/B test), D: «Новая кампания» (New campaign)."}, {"id": "q12", "image": "images/5-2/q12.jpg", "prompt": "Rasmdagi jadvalga qarang. Bitta reklama guruhida nechta reklama bor va qolganlari qanday yaratilgan?", "options": [{"id": "a", "text": "3 ta. Ularning hammasi boshqa guruhga tegishli"}, {"id": "b", "text": "4 ta. Bitta reklama «Дублировать» (Duplicate) qilinib, 3 ta nusxa («Копия») yaratilgan"}, {"id": "c", "text": "1 ta. Qolganlari xato tufayli chiqib qolgan"}, {"id": "d", "text": "4 ta. Har biri alohida kampaniyada"}], "correct_option_id": "b", "explanation": "Nomlardagi «Копия» so'zi nusxa ekanini bildiradi. Bir guruhda bir nechta kreativ qo'yib, qaysi biri yaxshiroq ishlashini sinash mumkin."}]$json$::jsonb, true)
on conflict (id) do update set title = excluded.title, questions = excluded.questions, section = excluded.section, section_order = excluded.section_order, lesson_order = excluded.lesson_order;

insert into public.tests(id, section, section_order, lesson_order, title, questions, published) values (
'5-3r', '5. Reklama kampaniyalari', 5, 3, '3. Lead (Lid) kampaniyasi — rasmli 🖼', $json$[{"id": "q1", "image": "images/5-3/q1.jpg", "keep_order": true, "prompt": "Reklama guruhining «Конверсия» bo'limi. Odam reklamadan saytga o'tib, lidni saytda qoldirishi uchun qaysi variantni tanlaysiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "c", "explanation": "C: «Сайт» (Website). Saytdagi lid pixel'dagi Lead eventi orqali hisoblanadi. A: «Instagram», B: «Моментальные формы» (Instant forms), D: «Звонки» (Calls)."}, {"id": "q2", "image": "images/5-3/q2.jpg", "keep_order": true, "prompt": "«Цель по результативности» (Performance goal) ro'yxati ochiq. Saytda lid qoldiradigan odamlarni topish uchun qaysi variantni tanlaysiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "d", "explanation": "D: «Максимальное число конверсий» (Maximize conversions). Klik ko'p bo'lsa ham lid kam bo'lishi mumkin. Konversiya tanlansa, Facebook aynan lid qoldiradiganlarni qidiradi. A: «Максимальное число просмотров целевой страницы» (Landing page views), B: «Максимальное число показов» (Impressions), C: «Максимальное число кликов по ссылке» (Link clicks)."}, {"id": "q3", "image": "images/5-3/q3.jpg", "keep_order": true, "prompt": "Pixel ro'yxatda chiqmadi, uni sozlash uchun Business Manager sozlamalariga o'tmoqchisiz. Biznes akkaunt yonidagi qaysi belgini bosasiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "a", "explanation": "A: tishli g'ildirak — «Настройки компании» (Business settings). Ustoz BM sozlamalarini yangi oynada ochib, pixelga ruxsat va reklama akkauntini biriktirdi. B: «Выйти» (Log out), C: «Найти аккаунты и компанию» qidiruvi, D: «Создать бизнес-аккаунт» (Create business account)."}, {"id": "q4", "image": "images/5-3/q4.jpg", "keep_order": true, "prompt": "Pixelga odam qo'shish oynasi. Odam shu pixel bo'yicha reklama yarata olishi va hamma sozlamalarni boshqarishi uchun qaysi kalitni yoqasiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "a", "explanation": "A: «Полный контроль» — «Управлять группой данных событий» (Manage dataset). To'liq nazorat yoqilsa, qisman ruxsat o'zi ham yoqilib qoladi. Keyin «Назначить» bosiladi. B: «Частичный доступ» (Partial access), C: «Назначить» (Assign) tugmasi, D: oynani yopish (X)."}, {"id": "q5", "image": "images/5-3/q5.jpg", "prompt": "Pixel sozlamalarida «Добавить ресурсы» oynasi ochilib, reklama akkaunti tanlanmoqda. Bu nima uchun kerak?", "options": [{"id": "a", "text": "Pixelni reklama akkauntiga ulash uchun: shundan keyin pixel Ads Manager'dagi «Пиксель» ro'yxatida chiqadi"}, {"id": "b", "text": "Pixel nomini o'zgartirish uchun"}, {"id": "c", "text": "Yangi reklama akkaunti ochish uchun"}, {"id": "d", "text": "Pixelni o'chirib tashlash uchun"}], "correct_option_id": "a", "explanation": "Pixel reklama akkauntiga biriktirilmagan bo'lsa, reklama yaratishda uni tanlab bo'lmaydi."}, {"id": "q6", "image": "images/5-3/q6.jpg", "keep_order": true, "prompt": "«Событие конверсии» (Conversion event) ro'yxati. Lid yig'ish kampaniyasi uchun qaysi eventni tanlaysiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "c", "explanation": "C: «Лид» (Lead). Saytga Lead eventi o'rnatilgan va kampaniya maqsadi lid bo'lgani uchun aynan shu event tanlanadi. A: «Просмотр контента» (View content), B: «Подписка» (Subscribe), D: «Завершенная регистрация» (Complete registration)."}, {"id": "q7", "image": "images/5-3/q7.jpg", "keep_order": true, "prompt": "«Бюджет и график». 1-martdan 9-martgacha bo'ladigan aksiya uchun jami 350 dollar ajratmoqchisiz. Byudjet turini qayerda tanlaysiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "a", "explanation": "A: byudjet turi ro'yxati — «Бюджет на весь срок действия» (Lifetime budget). Ro'yxatdan kunlik yoki butun muddat uchun byudjet tanlanadi. Umumiy byudjetda tugash sanasi ham belgilanadi. B: «Увеличьте бюджет в определенные периоды» belgisi, C: «Дата окончания» (End date), D: «Дата начала» (Start date)."}, {"id": "q8", "image": "images/5-3/q8.jpg", "prompt": "Rasmdagi sozlamaga ko'ra reklama qanday ishlaydi?", "options": [{"id": "a", "text": "1-martdan 9-martgacha jami 350 dollar sarflanadi, Facebook pulni shu kunlar orasida o'zi taqsimlaydi"}, {"id": "b", "text": "Har kuni 350 dollardan sarflanadi"}, {"id": "c", "text": "Reklama faqat 1-mart kuni ishlaydi"}, {"id": "d", "text": "Reklama hech qachon to'xtamaydi"}], "correct_option_id": "a", "explanation": "«Бюджет на весь срок действия» tanlangan. Ba'zi kunlari ko'proq, ba'zi kunlari kamroq sarflanishi mumkin, lekin jami 350 dollardan oshmaydi."}, {"id": "q9", "image": "images/5-3/q9.jpg", "prompt": "Joylashuvda «Ташкент» tanlangan va xaritada aylana ko'rinyapti. Bu nimani bildiradi?", "options": [{"id": "a", "text": "Reklama butun O'zbekistonga ko'rsatiladi"}, {"id": "b", "text": "Reklama faqat Toshkentdan tashqaridagilarga ko'rsatiladi"}, {"id": "c", "text": "Bu Facebook ofisining manzili"}, {"id": "d", "text": "Reklama Toshkent va uning atrofidagi belgilangan radius ichidagi odamlarga ko'rsatiladi"}], "correct_option_id": "d", "explanation": "Shahar tanlanganda uning atrofidagi radiusni ham o'zgartirish mumkin. Butun O'zbekistonni tanlash ham mumkin."}, {"id": "q10", "image": "images/5-3/q10.jpg", "keep_order": true, "prompt": "Auditoriyaning minimal yoshini 25 qilmoqchisiz. Qaysi ro'yxatni ochasiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "c", "explanation": "C: chapdagi yosh ro'yxati (hozir 18). Chapdagi ro'yxat eng kichik yoshni, o'ngdagisi eng katta yoshni belgilaydi. Darsda 25–35 tanlandi. A: «Поставить метку» (Drop pin), B: «Включить» (Include), D: o'ngdagi yosh ro'yxati (65+)."}, {"id": "q11", "image": "images/5-3/q11.jpg", "keep_order": true, "prompt": "Dyson soch quritgichini faqat ayollarga ko'rsatmoqchisiz. «Пол» (Gender) qismida qaysi variantni tanlaysiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "c", "explanation": "C: «Женщины» (Women). Mahsulot ayollar uchun bo'lgani uchun ustoz faqat ayollarni tanladi. A: «Мужчины» (Men), B: «Все» (All), D: «Исключить» (Exclude)."}, {"id": "q12", "image": "images/5-3/q12.jpg", "prompt": "«Места размещения Advantage+» (Advantage+ placements) tanlansa nima bo'ladi?", "options": [{"id": "a", "text": "Reklama faqat Instagram stories'da chiqadi"}, {"id": "b", "text": "Reklama hech qayerda ko'rsatilmaydi"}, {"id": "c", "text": "Facebook byudjetni turli joylashuvlar orasida o'zi taqsimlaydi va natija yaxshiroq bo'ladigan joyga ko'proq sarflaydi"}, {"id": "d", "text": "Reklama faqat Facebook lentasida chiqadi"}], "correct_option_id": "c", "explanation": "Pastdagi «Выбор мест размещения вручную» tanlansa, joylashuvlar qo'lda belgilanadi."}, {"id": "q13", "image": "images/5-3/q13.jpg", "prompt": "Reklama sahifasida qizil xato chiqdi. Uni qanday tuzatish mumkin?", "options": [{"id": "a", "text": "Pixelni qaytadan yaratish kerak"}, {"id": "b", "text": "Byudjetni oshirish kerak"}, {"id": "c", "text": "Instagram akkauntga profil rasmi qo'yish kerak: rasmsiz akkauntdan reklama Instagram'da ko'rsatilmaydi"}, {"id": "d", "text": "Facebook sahifani o'chirish kerak"}], "correct_option_id": "c", "explanation": "Ustoz Instagram'ga kirib, profilga rasm qo'ydi. Shundan keyin xato yo'qoldi."}, {"id": "q14", "image": "images/5-3/q14.jpg", "keep_order": true, "prompt": "Reklama formati bo'limi. Bitta rasm yoki bitta video bilan reklama qilmoqchisiz. Qaysi formatni tanlaysiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "c", "explanation": "C: «Одно изображение или видео» (Single image or video). Karusel 2 va undan ko'p rasm uchun, «Подборка» esa mobil telefonda to'liq ekranda ochiladigan to'plam uchun. A: «Кольцевая галерея» (Carousel), B: «Добавить медиафайл» (Add media), D: «Подборка» (Collection)."}, {"id": "q15", "image": "images/5-3/q15.jpg", "prompt": "«Оптимизация объявления с помощью креатива Advantage+» oynasi. Bu yerda Facebook reklamaga nimalarni o'zi qo'shishi mumkin?", "options": [{"id": "a", "text": "Reklamani o'zi to'xtatadi"}, {"id": "b", "text": "Musiqa, dolzarb izohlar, rasm filtri kabi o'zgarishlarni avtomatik qo'shadi"}, {"id": "c", "text": "Byudjetni o'zi oshiradi"}, {"id": "d", "text": "Auditoriyani o'zi o'chirib tashlaydi"}], "correct_option_id": "b", "explanation": "Ustoz Facebook tanlaydigan musiqa va izohlar reklamaga mos kelmasligi mumkinligini aytdi. Har bir funksiyani o'chirib qo'yish mumkin."}, {"id": "q16", "image": "images/5-3/q16.jpg", "keep_order": true, "prompt": "Reklama matni yoziladigan joy. Rasm tepasida chiqadigan asosiy matnni qaysi maydonga yozasiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "b", "explanation": "B: «Основной текст» (Primary text). Asosiy matn Facebook va Instagram'da rasm tepasida, sarlavha esa rasm ostida chiqadi. Har biriga 5 tagacha variant yozish mumkin. A: «Добавить вариант текста» (Add text option), C: «Добавить вариант заголовка» (Add headline option), D: «Заголовок» (Headline)."}, {"id": "q17", "image": "images/5-3/q17.jpg", "keep_order": true, "prompt": "«Призыв к действию» (Call to action) ro'yxati ochiq. Reklama tugmasida «Buyurtma berish» yozuvi chiqishi uchun qaysi variantni tanlaysiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "d", "explanation": "D: «Заказать» (Order now). Ustoz Dyson reklamasi uchun «Заказать» tugmasini tanladi. A: «В магазин» (Shop now), B: «Регистрация» (Sign up), C: «Подробнее» (Learn more)."}, {"id": "q18", "image": "images/5-3/q18.jpg", "keep_order": true, "prompt": "«Место назначения» (Destination). Tugma bosilganda odam ochiladigan sayt manzilini qaysi maydonga yozasiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "a", "explanation": "A: «URL сайта» (Website URL). «Отображаемая ссылка» faqat reklamada ko'rinadigan qisqa yozuv. Odam aynan «URL сайта»dagi manzilga o'tadi. B: «Позвонить» (Call) varianti, C: «Отображаемая ссылка» (Display link), D: «Нет» (None) varianti."}, {"id": "q19", "image": "images/5-3/q19.jpg", "prompt": "«Дополнения браузера» (Browser add-ons) bo'limida «Позвонить» (Call) tanlansa nima bo'ladi?", "options": [{"id": "a", "text": "Reklama faqat telefon qo'ng'irog'i orqali ishlaydi"}, {"id": "b", "text": "Odamga avtomatik SMS yuboriladi"}, {"id": "c", "text": "Saytingiz o'chib qoladi"}, {"id": "d", "text": "Sayt reklamadan ochilganda unga qo'ng'iroq qilish tugmasi qo'shiladi"}], "correct_option_id": "d", "explanation": "Ustoz saytda ma'lumot o'qib, keyin o'zi forma to'ldirishi kerak bo'lgani uchun qo'ng'iroq tugmasini qo'shmadi."}, {"id": "q20", "image": "images/5-3/q20.jpg", "keep_order": true, "prompt": "Hamma sozlamalar tayyor. Reklamani tekshiruvga yuborib, ishga tushirish uchun qaysi tugmani bosasiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "d", "explanation": "D: «Опубликовать» (Publish). Facebook avval reklamani tekshiradi, tasdiqlangandan keyin reklama ko'rsatila boshlaydi. A: «Закрыть» (Close), B: «Настроить» (Set up), C: «Назад» (Back)."}]$json$::jsonb, true)
on conflict (id) do update set title = excluded.title, questions = excluded.questions, section = excluded.section, section_order = excluded.section_order, lesson_order = excluded.lesson_order;

insert into public.tests(id, section, section_order, lesson_order, title, questions, published) values (
'5-4r', '5. Reklama kampaniyalari', 5, 4, '4. Brendni tanitish kampaniyasi — rasmli 🖼', $json$[{"id": "q1", "image": "images/5-4/q1.jpg", "keep_order": true, "prompt": "Brendni iloji boricha ko'p odamga tanitmoqchisiz. Qaysi kampaniya maqsadini tanlaysiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "a", "explanation": "A: «Узнаваемость» (Awareness). O'ngdagi tavsifda ham yozilgan: охват, brendni eslab qolish, video ko'rishlar. B: «Лиды» (Leads), C: «Трафик» (Traffic), D: «Продажи» (Sales)."}, {"id": "q2", "image": "images/5-4/q2.jpg", "prompt": "«Узнаваемость» maqsadi qaysi natijalar uchun mos ekani o'ng tomonda yozilgan. Ular qaysilar?", "options": [{"id": "a", "text": "Ilova o'rnatishlari va ilovadagi eventlar"}, {"id": "b", "text": "Sotuvlar va savatchaga qo'shishlar"}, {"id": "c", "text": "Lidlar, qo'ng'iroqlar va xabarlar"}, {"id": "d", "text": "«Охват» (Reach), «Прирост узнаваемости бренда» (Brand awareness), «Просмотры видео» (Video views), «Узнаваемость адреса точки» (Store location awareness)"}], "correct_option_id": "d", "explanation": "Bu maqsad darhol natija emas, balki ko'p odamga ko'rinish va brendni eslab qolish uchun."}, {"id": "q3", "image": "images/5-4/q3.jpg", "keep_order": true, "prompt": "Brend reklamasi uchun reklama guruhi. Reklamani iloji boricha ko'p alohida odamga ko'rsatish maqsadi qayerda tanlanadi?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "b", "explanation": "B: «Цель по результативности» (Performance goal) ro'yxati. Bu darsda maqsad ro'yxatidan «Максимальный рекламный охват» (Maximize reach) tanlandi. A: «Название группы объявлений» (Ad set name), C: «Страница Facebook» (Facebook Page), D: «Контрольная ставка» (Bid control)."}, {"id": "q4", "image": "images/5-4/q4.jpg", "keep_order": true, "prompt": "Reklamani iloji boricha ko'p alohida odamga, har biriga ko'pi bilan bir martadan ko'rsatmoqchisiz. Qaysi variantni tanlaysiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "c", "explanation": "C: «Максимальный рекламный охват» (Maximize reach). Показы esa reklamani ko'p marta ko'rsatadi, bitta odam uni bir necha marta ko'rishi mumkin. A: «Цели по просмотрам видео» (Video views goals), B: «Максимальное число показов» (Maximize impressions), D: «Максимальный прирост запоминаемости рекламы» (Ad recall lift)."}, {"id": "q5", "image": "images/5-4/q5.jpg", "keep_order": true, "prompt": "Video reklamani 15 soniya yoki oxirigacha ko'radigan odamlarga ko'rsatmoqchisiz. Qaysi variantni tanlaysiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "d", "explanation": "D: «Максимальное число просмотров ThruPlay». ThruPlay videoni oxirigacha yoki kamida 15 soniya ko'radiganlarni hisoblaydi. A: «Максимальное число непрерывных 2-секундных просмотров», B: «Максимальный рекламный охват», C: «Максимальное число показов»."}, {"id": "q6", "image": "images/5-4/q6.jpg", "keep_order": true, "prompt": "Facebook auksionda 1000 marta ko'rsatish uchun qancha to'lashi mumkinligini cheklamoqchisiz. Qaysi maydonga yozasiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "b", "explanation": "B: «Контрольная ставка» (Bid cap). Bu maydon ixtiyoriy («Необязательно»). Juda past qo'yilsa, reklama auksionda yutqazib, ko'rsatilmay qolishi mumkin. A: «Цель по результативности», C: «Страница Facebook», D: «Название группы объявлений»."}, {"id": "q7", "image": "images/5-4/q7.jpg", "keep_order": true, "prompt": "Brend reklamasiga kuniga 5 dollar sarflamoqchisiz. Summani qaysi maydonga yozasiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "c", "explanation": "C: «Дневной бюджет» yonidagi summa maydoni. Pastdagi yozuvda: o'rtacha kuniga 5 $, eng ko'pi bilan kuniga 6,25 $, haftasiga 35 $ sarflanadi. A: «Страница Facebook», B: «Контрольная ставка» (Bid control), D: «Динамические креативы» kaliti."}, {"id": "q8", "image": "images/5-4/q8.jpg", "prompt": "Reklama guruhi dublikat qilindi va nusxaning nomi «BROAD — Копия». Ustoz nusxani qanday nomlashni maslahat berdi?", "options": [{"id": "a", "text": "«Копия» nomini o'zgartirmaslikni"}, {"id": "b", "text": "Nomni butunlay o'chirib qo'yishni"}, {"id": "c", "text": "Ikkala guruhga bir xil nom berishni"}, {"id": "d", "text": "Nomga shu guruhdagi maqsadni yozishni, masalan «BROAD - Максимальное число показов», keyin qaysi guruh nima ekani ko'rinib turadi"}], "correct_option_id": "d", "explanation": "Ikkala guruhda охват va показы sinab ko'rilganda, aniq nomlar natijani to'g'ri solishtirishga yordam beradi."}, {"id": "q9", "image": "images/5-4/q9.jpg", "prompt": "Kampaniya maqsadi o'zgartirilganda shu oyna chiqdi. U nima haqida ogohlantiryapti?", "options": [{"id": "a", "text": "Yangi maqsad tanlangani uchun ba'zi joriy sozlamalar saqlanmasligi va standart holatga qaytishi mumkin"}, {"id": "b", "text": "Reklama akkaunti bloklanadi"}, {"id": "c", "text": "Byudjet avtomatik ikki baravar oshadi"}, {"id": "d", "text": "Kampaniya butunlay o'chirib yuboriladi"}], "correct_option_id": "a", "explanation": "Shuning uchun maqsadni boshidanoq to'g'ri tanlash kerak."}, {"id": "q10", "image": "images/5-4/q10.jpg", "keep_order": true, "prompt": "Auditoriya sozlamalari. Reklama ko'rsatiladigan davlat yoki shaharni qayerdan qo'shasiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "b", "explanation": "B: «Поиск местоположений» (Search locations). Joylashuv qo'shilmaguncha Facebook auditoriya hajmini hisoblay olmaydi. Darsda «Узбекистан» tanlandi. A: «Исключить эти пользовательские аудитории», C: «Минимальный возраст» (Minimum age), D: «Языки» (Languages)."}, {"id": "q11", "image": "images/5-4/q11.jpg", "keep_order": true, "prompt": "Advantage+ auditoriyasida ham reklamani 21 yoshdan kichiklarga ko'rsatmaslik mumkin. Buning uchun qaysi maydonni o'zgartirasiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "a", "explanation": "A: «Минимальный возраст» (Minimum age). Facebook auditoriyani o'zi qidiradi, lekin minimal yosh kabi cheklovlarni siz qo'yasiz. B: «Поиск языков» (Languages), C: «Исключить эти пользовательские аудитории», D: «Поставить метку» (Drop pin)."}, {"id": "q12", "image": "images/5-4/q12.jpg", "keep_order": true, "prompt": "Shu oyna chiqdi. Auditoriyani o'zingiz qo'lda sozlamoqchisiz. Qaysi tugmani bosasiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "a", "explanation": "A: «Использовать исходную аудиторию» (Use original audience). Ko'k tugma bosilsa, Facebook auditoriyani o'zi qidiradi. Oynada Advantage+ bilan natija narxi 33 foizgacha arzonlashishi mumkinligi yozilgan. B: oynani yopish (X), C: «Подробнее об аудитории Advantage+» havolasi, D: «Использовать аудиторию Advantage+»."}, {"id": "q13", "image": "images/5-4/q13.jpg", "keep_order": true, "prompt": "Joylashuvlarni qo'lda tanlab, reklamani faqat telefonlarda ko'rsatmoqchisiz. Avval qaysi variantni tanlaysiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "b", "explanation": "B: «Выбор мест размещения вручную» (Manual placements). Qo'lda tanlaganda «Устройства» (Devices) va platformalarni o'zingiz belgilaysiz. A: «Места размещения Advantage+» (Advantage+ placements), C: «Facebook» platformasi, D: 4 kunlik A/B-test belgisi."}, {"id": "q14", "image": "images/5-4/q14.jpg", "prompt": "«Устройства» (Devices) ro'yxatida «ПК» tanlangan. Bu nimani bildiradi?", "options": [{"id": "a", "text": "Reklama hamma qurilmalarda ko'rsatiladi"}, {"id": "b", "text": "Reklama faqat planshetlarda ko'rsatiladi"}, {"id": "c", "text": "Reklama faqat kompyuterlarda ko'rsatiladi, telefonlarda chiqmaydi"}, {"id": "d", "text": "Reklama faqat telefonlarda ko'rsatiladi"}], "correct_option_id": "c", "explanation": "Ustoz ko'pchilik odam telefondan foydalanishini aytdi, shuning uchun kompyuterni alohida tanlash kamdan-kam kerak bo'ladi."}, {"id": "q15", "image": "images/5-4/q15.jpg", "keep_order": true, "prompt": "Qaysi platformada (Facebook, Instagram, Messenger, Audience Network) reklama chiqishini qayerda belgilaysiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "a", "explanation": "A: «Платформы» ostidagi belgilar (masalan, Facebook). Belgini olib tashlasangiz, reklama o'sha platformada ko'rsatilmaydi. B: «Места размещения Advantage+», C: 4 kunlik A/B-test belgisi, D: «Устройства» (Devices) ro'yxati."}, {"id": "q16", "image": "images/5-4/q16.jpg", "keep_order": true, "prompt": "Joylashuvlar ro'yxati. Reklamani Reels va stories'da ko'rsatmaslik uchun qaysi belgini olib tashlaysiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "b", "explanation": "B: «Истории и видео Reels» (Stories and Reels). Har bir joylashuv yonidagi belgi o'sha joyda reklama chiqish-chiqmasligini belgilaydi. A: «Результаты поиска» (Search results), C: «Ленты» (Feeds), D: «Реклама In-Stream для видео и Reels»."}, {"id": "q17", "image": "images/5-4/q17.jpg", "keep_order": true, "prompt": "Ilovangiz faqat iPhone uchun. Reklamani faqat iPhone egalariga ko'rsatish uchun qaysi variantni tanlaysiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "d", "explanation": "D: «Только устройства iOS» (iOS devices only). Ustoz misoli: ilova faqat iOS'da bo'lsa, reklamani faqat iPhone egalariga ko'rsatish kerak. A: «Все мобильные устройства» (All mobile devices), B: «Только устройства Android» (Android devices only), C: «Только многофункциональные телефоны» (Feature phones only)."}, {"id": "q18", "image": "images/5-4/q18.jpg", "prompt": "Rasmda «Только устройства Android» va «Версии ОС» sozlamalari ko'rinyapti. Qurilmani shunday toraytirsangiz, auditoriya bilan nima bo'ladi?", "options": [{"id": "a", "text": "Reklama bepul bo'ladi"}, {"id": "b", "text": "Auditoriya kichrayadi va reklama odatda qimmatroq tushadi"}, {"id": "c", "text": "Auditoriya kattalashadi"}, {"id": "d", "text": "Hech narsa o'zgarmaydi"}], "correct_option_id": "b", "explanation": "Kerak bo'lsa, tizim versiyasi bo'yicha ham cheklash mumkin, masalan eski telefonlarga reklama ko'rsatmaslik."}, {"id": "q19", "image": "images/5-4/q19.jpg", "keep_order": true, "prompt": "Reklama bosqichi. Bir nechta rasm yoki videoni yonga suriladigan qilib ko'rsatmoqchisiz. Qaysi formatni tanlaysiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "b", "explanation": "B: «Кольцевая галерея» (Carousel). Karuselda kamida 2 ta rasm yoki video bo'ladi. A: «Одно изображение или видео», C: «Создать рекламу» ro'yxati, D: «Подборка» (Collection)."}, {"id": "q20", "image": "images/5-4/q20.jpg", "keep_order": true, "prompt": "Media fayl tanlash oynasi. Kompyuteringizdagi yangi videoni yuklash uchun qaysi tugmani bosasiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "c", "explanation": "C: «Загрузить» (Upload). Video Facebook'ka yuklanishi biroz vaqt olishi mumkin, u orqa fonda yuklanadi. A: «Далее» (Next), B: «Фильтры» (Filters), D: «Отмена» (Cancel)."}]$json$::jsonb, true)
on conflict (id) do update set title = excluded.title, questions = excluded.questions, section = excluded.section, section_order = excluded.section_order, lesson_order = excluded.lesson_order;

insert into public.tests(id, section, section_order, lesson_order, title, questions, published) values (
'5-5r', '5. Reklama kampaniyalari', 5, 5, '5. Karusel format — rasmli 🖼', $json$[{"id": "q1", "image": "images/5-5/q1.jpg", "keep_order": true, "prompt": "Bir nechta rasmni yonga surib ko'riladigan qilib reklama qilmoqchisiz. Qaysi formatni tanlaysiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "d", "explanation": "D: «Кольцевая галерея» (Carousel). Karusel tagidagi tavsifda ham yozilgan: 2 va undan ko'p rasm yoki video, yonga suriladi. A: «Одно изображение или видео», B: «Подборка» (Collection), C: «Объявления в рекламном блоке…» belgisi."}, {"id": "q2", "image": "images/5-5/q2.jpg", "prompt": "Rasm tanlash oynasining sarlavhasiga qarang. Karuselga ko'pi bilan nechta rasm qo'shish mumkin?", "options": [{"id": "a", "text": "3 ta"}, {"id": "b", "text": "Cheksiz"}, {"id": "c", "text": "10 ta («Выберите до 10 изображений»)"}, {"id": "d", "text": "5 ta"}], "correct_option_id": "c", "explanation": "Pastda «Выбранные изображения (2 из 10)» deb ham yozilgan."}, {"id": "q3", "image": "images/5-5/q3.jpg", "prompt": "Ba'zi rasmlar yonida qizil yoki sariq belgi bor va tepada «Медиафайл находится на проверке» deb yozilgan. Bu nimani bildiradi?", "options": [{"id": "a", "text": "Facebook yangi rasmlarni reklama qoidalariga tekshiradi. Belgi qo'yilgan rasm qoidalarga to'g'ri kelmasligi mumkin"}, {"id": "b", "text": "Bu rasmlar allaqachon sotilgan"}, {"id": "c", "text": "Bu rasmlar faqat Instagram uchun"}, {"id": "d", "text": "Bu rasmlar eng yaxshi natija bergan"}], "correct_option_id": "a", "explanation": "Ogohlantirish belgisi bor rasmni ishlatmagan ma'qul."}, {"id": "q4", "image": "images/5-5/q4.jpg", "keep_order": true, "prompt": "Karuselga 5 ta karta qo'shildi. Yana bitta karta qo'shish uchun qaysi tugmani bosasiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "d", "explanation": "D: «Добавить карты» (Add cards). Tepada «Добавлено 5 из 10 карточек» deb yozilgan: yana 5 ta karta qo'shish mumkin. A: «Редактировать место размещения», B: birinchi kartani tahrirlash belgisi, C: «Смотреть варианты» (See variations)."}, {"id": "q5", "image": "images/5-5/q5.jpg", "keep_order": true, "prompt": "Karta ochildi. Shu kartaga o'z sarlavhasini qaysi maydonga yozasiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "d", "explanation": "D: «Заголовок» (Headline). Karuseldagi har bir kartaga alohida sarlavha, tavsif va havola yoziladi. A: «Описание» (Description), B: «URL сайта» (Website URL), C: «Редактировать» (Edit) tugmasi."}, {"id": "q6", "image": "images/5-5/q6.jpg", "keep_order": true, "prompt": "Karusel qaysi joylashuvda qanday ko'rinishini alohida o'zgartirmoqchisiz. Qaysi ro'yxatni ochasiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "c", "explanation": "C: «Редактировать место размещения» (Edit placement). Ro'yxatdan joylashuv tanlanadi, masalan, Instagram lentasi yoki Reels. A: oxirgi kartani tahrirlash belgisi, B: «Добавить карты» (Add cards), D: «Удалить» (Delete)."}, {"id": "q7", "image": "images/5-5/q7.jpg", "keep_order": true, "prompt": "Bitta joylashuv uchun karusel tahrirlanyapti. 1-kartadagi rasmni boshqasiga almashtirish uchun qaysi bandni tanlaysiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "a", "explanation": "A: «Изменить» (Change) — media faylni almashtirish. O'ngda «Изменить медиафайл» ochiladi va yangi rasm tanlanadi. B: «Удалить карточку» (Delete card), C: «Destination» (havola), D: «Кадрировать» (Crop)."}, {"id": "q8", "image": "images/5-5/q8.jpg", "keep_order": true, "prompt": "Karta bosilganda odam ochiladigan sayt manzilini qaysi joyda o'zgartirasiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "b", "explanation": "B: «URL сайта» (Website URL) maydoni. Har bir karta o'z mahsuloti sahifasiga olib borsa, odam qidirib yurmaydi. A: «Удалить карточку» (Delete card), C: «Заголовок» (Headline), D: «Альтернативный текст для изображения»."}, {"id": "q9", "image": "images/5-5/q9.jpg", "keep_order": true, "prompt": "Karuselning hamma kartalari uchun umumiy asosiy matnni qaysi maydonga yozasiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "a", "explanation": "A: «Основной текст» (Primary text). Sarlavhalar har bir kartada alohida, asosiy matn esa hamma kartalar uchun umumiy. B: «Призыв к действию» (Call to action), C: «Редактировать» (Advantage+ kreativ), D: «Редактировать место размещения»."}]$json$::jsonb, true)
on conflict (id) do update set title = excluded.title, questions = excluded.questions, section = excluded.section, section_order = excluded.section_order, lesson_order = excluded.lesson_order;

insert into public.tests(id, section, section_order, lesson_order, title, questions, published) values (
'5-6r', '5. Reklama kampaniyalari', 5, 6, '6. Trafik kampaniyasi — rasmli 🖼', $json$[{"id": "q1", "image": "images/5-6/q1.jpg", "keep_order": true, "prompt": "Odamlarni saytingizga ko'proq olib kelmoqchisiz. Qaysi kampaniya maqsadini tanlaysiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "d", "explanation": "D: «Трафик» (Traffic). Trafik odamlarni sayt, ilova, Instagram profil yoki messenjer kabi manzilga yuboradi. A: «Продажи» (Sales), B: «Вовлеченность» (Engagement), C: «Узнаваемость» (Awareness)."}, {"id": "q2", "image": "images/5-6/q2.jpg", "prompt": "O'ng tomondagi «Для чего подходит» ro'yxatiga ko'ra trafik maqsadi qaysi natijalar uchun mos?", "options": [{"id": "a", "text": "Faqat ilova o'rnatishlari"}, {"id": "b", "text": "Faqat brendni eslab qolish"}, {"id": "c", "text": "Havola bosishlar, sahifa ko'rishlar, Messenger/Instagram/WhatsApp, qo'ng'iroqlar va Instagram profilga kirishlar"}, {"id": "d", "text": "Faqat sotuvlar"}], "correct_option_id": "c", "explanation": "«Клики по ссылке», «Просмотры целевой страницы», «Messenger, Instagram и WhatsApp», «Звонки», «Посещения профиля Instagram»."}, {"id": "q3", "image": "images/5-6/q3.jpg", "keep_order": true, "prompt": "Trafik kampaniyasi. Odamlarni saytga yuborish uchun «Место получения конверсий» qismida qaysi variantni tanlaysiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "d", "explanation": "D: «Сайт» (Website). Ustoz bu darsda saytni tanladi. Ilovani tanlash uchun avval BMga ilova ulangan bo'lishi kerak. A: «Звонки» (Calls), B: «Профиль Instagram» (Instagram profile), C: «Приложение» (App)."}, {"id": "q4", "image": "images/5-6/q4.jpg", "keep_order": true, "prompt": "Reklama bosilganda odam sizga Messenger, Instagram yoki WhatsApp orqali yozishi uchun qaysi variantni tanlaysiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "d", "explanation": "D: «Приложения для обмена сообщениями» (Messaging apps). Keyin pastda qaysi messenjerlarga yozish mumkinligi belgilanadi. A: «Звонки» (Calls), B: «Сайт» (Website), C: «Профиль Instagram» (Instagram profile)."}, {"id": "q5", "image": "images/5-6/q5.jpg", "prompt": "«Профиль Instagram» tanlandi. Natija maqsadi qanday o'zgardi va bu nimaga kerak?", "options": [{"id": "a", "text": "«Максимальное число конверсий»: saytda sotuv qilish uchun"}, {"id": "b", "text": "«Максимальное число посещений профиля Instagram»: reklama bosilganda Instagram profil ochiladi, bu obunachilarni ko'paytirish uchun qulay"}, {"id": "c", "text": "«Максимальный охват»: brendni tanitish uchun"}, {"id": "d", "text": "«Максимальное число установок приложения»: ilova uchun"}], "correct_option_id": "b", "explanation": "Odam profilingizga tushib, obuna bo'lishi mumkin."}, {"id": "q6", "image": "images/5-6/q6.jpg", "keep_order": true, "prompt": "Tugmani bosib, saytni haqiqatan ochib ko'radigan odamlarni topmoqchisiz. Qaysi variantni tanlaysiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "b", "explanation": "B: «Максимальное число просмотров целевой страницы» (Landing page views). Klik ko'p bo'lsa ham, internet sekinligi yoki sayt yuklanguncha chiqib ketish sababli odam sahifani ko'rmasligi mumkin. A: «Приложение» (App), C: «Другие цели» (Other goals), D: «Максимальное число кликов по ссылке» (Link clicks)."}, {"id": "q7", "image": "images/5-6/q7.jpg", "prompt": "O'ngdagi bashoratda 222–642 «Просмотры целевой страницы» ko'rsatilgan. Bu raqamlar haqida ustoz nima dedi?", "options": [{"id": "a", "text": "Bu raqobatchilarning natijasi"}, {"id": "b", "text": "Bu kafolatlangan natija"}, {"id": "c", "text": "Bu o'tgan oyning natijasi"}, {"id": "d", "text": "Bu taxminiy raqamlar, aniq emas. Ular byudjet va auditoriyaga qarab hisoblanadi"}], "correct_option_id": "d", "explanation": "Pastdagi izohda ham bashorat faqat taxminiy ekani yozilgan."}, {"id": "q8", "image": "images/5-6/q8.jpg", "prompt": "Sayt tanlangan holda «Максимальное число переписок» tanlanganda o'ngda sariq ogohlantirish chiqdi. U nimani bildiradi?", "options": [{"id": "a", "text": "Byudjet tugadi"}, {"id": "b", "text": "Reklama muvaffaqiyatli nashr qilindi"}, {"id": "c", "text": "Sozlamalar bir-biriga mos emas, shuning uchun reklama guruhida natija nol bo'lishi mumkin"}, {"id": "d", "text": "Auditoriya juda katta"}], "correct_option_id": "c", "explanation": "Saytga trafik yuborib, xabar (переписка) kutib bo'lmaydi. Maqsad manzilga mos bo'lishi kerak."}, {"id": "q9", "image": "images/5-6/q9.jpg", "keep_order": true, "prompt": "Reklama tugmasidagi yozuv ro'yxati ochiq. Odamni buyurtma berishga chaqirish uchun qaysi variantni tanlaysiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "a", "explanation": "A: «Заказать» (Order now). Tugma reklamaning maqsadiga mos tanlanadi. B: «Подробнее» (Learn more), C: «Скачать» (Download), D: «Слушать» (Listen now)."}, {"id": "q10", "image": "images/5-6/q10.jpg", "keep_order": true, "prompt": "Facebook sarlavha va asosiy matnning o'rnini o'zi almashtirmasligi uchun qaysi sozlamani o'chirasiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "a", "explanation": "A: «Оптимизировать текст для человека» (Text optimization). Ustoz bu funksiyani o'chirdi: aks holda Facebook matnlarni o'zi tanlab, ularning o'rnini almashtirishi mumkin. B: «Описание» (Description), C: «Заголовок» (Headline), D: «Призыв к действию» (Call to action)."}, {"id": "q11", "image": "images/5-6/q11.jpg", "prompt": "«Инфометки» (Info labels) oynasi ochiq. Bu funksiya nima uchun kerak?", "options": [{"id": "a", "text": "Reklamada muhim ma'lumotni belgicha bilan ko'rsatish uchun: bepul yetkazib berish, to'lov usullari, qaytarish shartlari"}, {"id": "b", "text": "Auditoriyani tanlash uchun"}, {"id": "c", "text": "Pixel o'rnatish uchun"}, {"id": "d", "text": "Reklama byudjetini oshirish uchun"}], "correct_option_id": "a", "explanation": "Ro'yxatda «Бесплатная доставка», «Варианты оплаты» va «Правила возврата» bor."}, {"id": "q12", "image": "images/5-6/q12.jpg", "keep_order": true, "prompt": "Sayt reklamadan ochilganda unga qo'ng'iroq tugmasi qo'shilishi uchun «Дополнения браузера» qismida qaysi variantni tanlaysiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "d", "explanation": "D: «Позвонить» (Call). Keyin pastdagi maydonga telefon raqami yoziladi. A: «Мероприятие Facebook» (Facebook event), B: «Нет» (None), C: «WhatsApp»."}, {"id": "q13", "image": "images/5-6/q13.jpg", "keep_order": true, "prompt": "Reklama tugmasi bosilganda odam ochiladigan sayt manzilini qaysi maydonga yozasiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "c", "explanation": "C: «URL сайта» (Website URL). «Отображаемая ссылка» faqat reklamada ko'rinadigan yozuv, odam esa «URL сайта»dagi manzilga o'tadi. A: «Instant Experience», B: «Отображаемая ссылка» (Display link), D: «Номер телефона» (Phone number)."}, {"id": "q14", "image": "images/5-6/q14.jpg", "keep_order": true, "prompt": "Reklamadan saytga kirganlarning harakatlarini pixel orqali kuzatish uchun qaysi belgini yoqasiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "b", "explanation": "B: «События на сайте» (Website events). Belgi yoqilgach, pixel tanlanadi va saytdagi eventlar reklama bilan bog'lanadi. A: «Языки» (Languages) kaliti, C: «Офлайн-события» (Offline events), D: «Настроить» («События в приложении»)."}]$json$::jsonb, true)
on conflict (id) do update set title = excluded.title, questions = excluded.questions, section = excluded.section, section_order = excluded.section_order, lesson_order = excluded.lesson_order;

insert into public.tests(id, section, section_order, lesson_order, title, questions, published) values (
'5-7r', '5. Reklama kampaniyalari', 5, 7, '7. Вовлеченность kampaniyasi — rasmli 🖼', $json$[{"id": "q1", "image": "images/5-7/q1.jpg", "keep_order": true, "prompt": "Videongizni ko'proq odam ko'rishi, layk va izohlar ko'payishi uchun qaysi kampaniya maqsadini tanlaysiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "b", "explanation": "B: «Вовлеченность» (Engagement). Вовлеченность odamlar reklama bilan o'zaro aloqa qilishini kutadi: video ko'rish, layk, izoh, xabar. A: «Узнаваемость» (Awareness), C: «Лиды» (Leads), D: «Трафик» (Traffic)."}, {"id": "q2", "image": "images/5-7/q2.jpg", "prompt": "O'ngdagi «Для чего подходит» ro'yxatiga ko'ra «Вовлеченность» qaysi natijalar uchun mos?", "options": [{"id": "a", "text": "Messenger/Instagram/WhatsApp'dagi xabarlar, video ko'rishlar, publikatsiya bilan o'zaro aloqa, konversiyalar va qo'ng'iroqlar"}, {"id": "b", "text": "Faqat brend haqidagi so'rovnomalar"}, {"id": "c", "text": "Faqat saytdagi sotuvlar"}, {"id": "d", "text": "Faqat ilova o'rnatishlari"}], "correct_option_id": "a", "explanation": "Bu maqsad odam bilan qandaydir o'zaro aloqani kutadi, faqat ko'rsatish bilan cheklanmaydi."}, {"id": "q3", "image": "images/5-7/q3.jpg", "keep_order": true, "prompt": "Odamlar reklamaning o'zida videoni ko'rishi yoki unga layk bosishi kerak. «Место получения конверсий» qismida qaysi variantni tanlaysiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "d", "explanation": "D: «Ваше объявление» (On your ad). «Ваше объявление» — o'zaro aloqa reklamaning ichida bo'ladi: video ko'rish, layk, izoh. A: «Страница Facebook» (Facebook Page), B: «Сайт» (Website), C: «Приложения для обмена сообщениями» (Messaging apps)."}, {"id": "q4", "image": "images/5-7/q4.jpg", "prompt": "«Сайт» tanlanganda konversiya eventi ro'yxati ochildi. «Active events» ostidagi «Просмотр контента» nimani bildiradi?", "options": [{"id": "a", "text": "Bu Facebook taklif qilgan yangi event, u hali saytda yo'q"}, {"id": "b", "text": "Bu event pixel orqali saytdan hozir ma'lumot olib turibdi, shuning uchun uni tanlash mumkin"}, {"id": "c", "text": "Bu event faqat ilovada ishlaydi"}, {"id": "d", "text": "Bu event o'chirib tashlangan"}], "correct_option_id": "b", "explanation": "«Inactive events» saytda o'rnatilmagan yoki hali ma'lumot kelmagan eventlar."}, {"id": "q5", "image": "images/5-7/q5.jpg", "keep_order": true, "prompt": "«Тип вовлеченности» ro'yxati ochiq. Videoni ko'proq odam ko'rishi uchun qaysi turni tanlaysiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "a", "explanation": "A: «Просмотры видео» (Video views). Ustoz bu maqsaddan asosan videosini ko'proq odam ko'rishi uchun foydalanadi. B: «Установленные напоминания» (Reminders set), C: «Ответы на приглашения» (Event responses), D: «Взаимодействие с публикацией» (Post engagement)."}, {"id": "q6", "image": "images/5-7/q6.jpg", "keep_order": true, "prompt": "Videoni 15 soniya yoki oxirigacha ko'radigan odamlarga ko'rsatmoqchisiz. Qaysi variantni tanlaysiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "b", "explanation": "B: «Максимальное число просмотров ThruPlay». ThruPlay videoni uzoqroq ko'radiganlarni topadi. A: «Цель по результативности» ro'yxatini yopish, C: «Тип вовлеченности» ro'yxati, D: «Максимальное число непрерывных 2-секундных просмотров видео»."}, {"id": "q7", "image": "images/5-7/q7.jpg", "prompt": "«Максимальное число непрерывных 2-секундных просмотров видео» tanlansa, Facebook kimlarni qidiradi?", "options": [{"id": "a", "text": "Faqat videoga izoh yozadiganlarni"}, {"id": "b", "text": "Videoni kamida 2 soniya uzluksiz ko'radiganlarni"}, {"id": "c", "text": "Faqat videoni ulashadiganlarni"}, {"id": "d", "text": "Videoni oxirigacha ko'radiganlarni"}], "correct_option_id": "b", "explanation": "2 soniyalik ko'rish ThruPlay'dan qisqaroq. Shuning uchun ko'proq, lekin qisqa ko'rishlar olinadi."}, {"id": "q8", "image": "images/5-7/q8.jpg", "keep_order": true, "prompt": "Reklama bosqichi. Maqsad video ko'rish bo'lgani uchun media fayl qo'shishda qaysi tugmani bosasiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "a", "explanation": "A: «Добавить видео» (Add video). Reklama guruhida maqsad video ko'rish bo'lgani uchun bu yerda rasm emas, faqat video qo'yiladi. B: «Добавить вариант текста» (Add text option), C: «Добавить место назначения» (Add destination), D: «Языки» (Languages) kaliti."}, {"id": "q9", "image": "images/5-7/q9.jpg", "keep_order": true, "prompt": "Video reklamaga tugma qo'shmoqchisiz. Odam bosganda sizga WhatsApp'da yozishi uchun qaysi variantni tanlaysiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "d", "explanation": "D: «Отправить сообщение в WhatsApp». Odatiy holatda video ko'rish reklamasida tugma bo'lmaydi, lekin uni qo'shish mumkin. Baribir Facebook videoni ko'radiganlarni qidiradi. A: «В магазин» (Shop now), B: «Подписаться» (Subscribe), C: «Отправить сообщение» (Send message)."}]$json$::jsonb, true)
on conflict (id) do update set title = excluded.title, questions = excluded.questions, section = excluded.section, section_order = excluded.section_order, lesson_order = excluded.lesson_order;

insert into public.tests(id, section, section_order, lesson_order, title, questions, published) values (
'5-8r', '5. Reklama kampaniyalari', 5, 8, '8. LID reklamasi (moment forma) — rasmli 🖼', $json$[{"id": "q1", "image": "images/5-8/q1.jpg", "keep_order": true, "prompt": "Lid kampaniyasi. Odam saytga o'tmasdan, Facebook yoki Instagram'ning o'zida forma to'ldirishi uchun qaysi variantni tanlaysiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "a", "explanation": "A: «Моментальные формы» (Instant forms). Moment forma ilovaning ichida ochiladi: odam ismi va telefon raqamini yozib, lid qoldiradi. B: «Messenger», C: «Сайт» (Website), D: «Звонки» (Calls)."}, {"id": "q2", "image": "images/5-8/q2.jpg", "keep_order": true, "prompt": "Moment forma tanlangach, pastda ogohlantirish chiqdi. Lid reklamasini yaratishdan oldin qaysi tugmani bosib, shartlarni ko'rib chiqasiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "a", "explanation": "A: «Условия» (Terms). Facebook'ning lid reklamasi shartlari bir marta qabul qilinadi, keyin forma yaratish mumkin. B: ogohlantirishni yopish (X), C: «Назад» (Back), D: «Страница Facebook» ro'yxati."}, {"id": "q3", "image": "images/5-8/q3.jpg", "prompt": "Lid «Сайт» orqali yig'ilganda pastda «Пиксель» maydoni chiqadi. Moment forma tanlansa nega pixel kerak bo'lmaydi?", "options": [{"id": "a", "text": "Odam saytga o'tmaydi, forma Facebook'ning o'zida to'ldiriladi. Pixel esa faqat saytdagi harakatlarni kuzatadi"}, {"id": "b", "text": "Pixel lidlarni o'chirib yuboradi"}, {"id": "c", "text": "Moment formada pixel pullik"}, {"id": "d", "text": "Pixel faqat Instagram'da ishlaydi"}], "correct_option_id": "a", "explanation": "Saytdan lid olishda pixel va Lead eventi tanlanadi. Moment formada sayt yo'q."}, {"id": "q4", "image": "images/5-8/q4.jpg", "keep_order": true, "prompt": "Reklama bosqichi. Yangi moment forma yaratish uchun qaysi tugmani bosasiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "b", "explanation": "B: «Создать форму» (Create form). «Моментальная форма» bo'limida forma yaratiladi yoki oldin yaratilgani tanlanadi. A: «Призыв к действию» ro'yxati, C: «События на сайте» belgisi, D: «Настроить» («События CRM»)."}, {"id": "q5", "image": "images/5-8/q5.jpg", "keep_order": true, "prompt": "Forma yaratish oynasi. Formaning nomini qayerga yozasiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "c", "explanation": "C: «Название формы» (Form name). Nom faqat sizga ko'rinadi. Keyin shu formani boshqa reklamalarda ham tanlash mumkin. A: «Вопросы» (Questions), B: «Высокое намерение» (Higher intent), D: «Краткая информация» (Intro)."}, {"id": "q6", "image": "images/5-8/q6.jpg", "keep_order": true, "prompt": "Faqat haqiqatan qiziqqan odamlardan sifatli lid olmoqchisiz: yuborishdan oldin odam ma'lumotlarini tekshirsin. Qaysi forma turini tanlaysiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "a", "explanation": "A: «Высокое намерение» (Higher intent). «Высокое намерение»da odam ma'lumotlarini tekshirib, tasdiqlaydi. Shuning uchun lidlar kamroq, lekin sifatliroq bo'ladi. B: «Увеличение объема» (More volume), C: «Сообщение для лидов» (Completion message), D: «Брендированный креатив» (Branded creative)."}, {"id": "q7", "image": "images/5-8/q7.jpg", "prompt": "Formada «Увеличение объема» (More volume) tanlangan. U qanday lid beradi?", "options": [{"id": "a", "text": "Faqat saytdagi xaridlarni"}, {"id": "b", "text": "Kam, lekin juda qimmat lid"}, {"id": "c", "text": "Ko'p va arzon lid beradi, chunki formani telefonda tez to'ldirib yuborish mumkin. Lekin sifati pastroq bo'lishi mumkin"}, {"id": "d", "text": "Faqat email manzillarni"}], "correct_option_id": "c", "explanation": "Tavsifda ham yozilgan: mobil qurilmadan tez to'ldirib yuboriladigan forma."}, {"id": "q8", "image": "images/5-8/q8.jpg", "keep_order": true, "prompt": "«Краткая информация» bo'limi. Forma foniga reklamadagi rasm qo'yilishi uchun qaysi variantni tanlaysiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "d", "explanation": "D: «Использовать изображение из вашей рекламы». Boshqa rasm qo'ymoqchi bo'lsangiz, ikkinchi variant tanlanadi. Tavsiya qilingan o'lcham 1200 × 628. A: «Тип формы», B: «Создать форму», C: «Использовать загруженное изображение»."}, {"id": "q9", "image": "images/5-8/q9.jpg", "prompt": "«Приветствие» (Greeting) bo'limida sarlavha va ro'yxat yozilgan. Forma ochilganda odam nimani ko'radi?", "options": [{"id": "a", "text": "Faqat telefon raqam maydonini"}, {"id": "b", "text": "Faqat Facebook sahifaning nomini"}, {"id": "c", "text": "Mahsulot haqidagi qisqa sarlavha va foydalari ro'yxati: tokka ulanmaydi, 20 ta kokteyl tayyorlaydi, muzni maydalaydi"}, {"id": "d", "text": "Reklama byudjetini"}], "correct_option_id": "c", "explanation": "O'ngdagi preview formaning birinchi oynasini ko'rsatadi: sarlavha va foydalar ro'yxati."}, {"id": "q10", "image": "images/5-8/q10.jpg", "prompt": "O'ngdagi preview'da «Contact information» ostida qaysi maydonlar qolgan?", "options": [{"id": "a", "text": "Pasport raqami va tug'ilgan sana"}, {"id": "b", "text": "Email va manzil"}, {"id": "c", "text": "Faqat Email"}, {"id": "d", "text": "«Full name» (ism-familiya) va «Phone number» (telefon raqam). Email olib tashlangan"}], "correct_option_id": "d", "explanation": "O'zbekistonda mijoz bilan asosan telefon orqali bog'laniladi, shuning uchun ustoz email o'rniga telefon raqamni qo'ydi."}, {"id": "q11", "image": "images/5-8/q11.jpg", "keep_order": true, "prompt": "Formaga yangi savol qo'shilmoqda. Variantli savol (masalan, 1, 2 yoki 3 xona) uchun qaysi turni tanlaysiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "c", "explanation": "C: «Несколько вариантов ответа» (Multiple choice). Variantli savollar mijozni oldindan saralashga yordam beradi. A: «Ползунок» (Slider), B: «Короткий ответ» (Short answer), D: «С условиями» (Conditional)."}, {"id": "q12", "image": "images/5-8/q12.jpg", "prompt": "Formaga «Necha xonalik uy olmoqchisiz?» degan savol qo'shildi. Savol qo'shish lidlarga qanday ta'sir qiladi?", "options": [{"id": "a", "text": "Forma ishlamay qoladi"}, {"id": "b", "text": "Lid sifatliroq bo'ladi, lekin qimmatroq va kamroq keladi"}, {"id": "c", "text": "Lid arzonlashadi va ko'payadi"}, {"id": "d", "text": "Hech qanday ta'sir qilmaydi"}], "correct_option_id": "b", "explanation": "Savol qancha ko'p bo'lsa, faqat haqiqatan qiziqqan odamlar formani oxirigacha to'ldiradi."}, {"id": "q13", "image": "images/5-8/q13.jpg", "keep_order": true, "prompt": "Odam o'z javobini erkin yozishi uchun formaga qaysi turdagi savolni qo'shasiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "d", "explanation": "D: «Короткий ответ» (Short answer). Tavsifda ham yozilgan: odamlar bir necha gap bilan qo'shimcha ma'lumot yoza oladi. A: «Запрос на встречу» (Appointment request), B: «Ползунок» (Slider), C: «Несколько вариантов ответа» (Multiple choice)."}, {"id": "q14", "image": "images/5-8/q14.jpg", "keep_order": true, "prompt": "«Политика конфиденциальности» bo'limi. Kompaniyangiz maxfiylik siyosati sahifasining havolasini qayerga qo'yasiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "d", "explanation": "D: «Ссылка» (Link). Bu majburiy maydon: odam ma'lumotlari qanday ishlatilishini bilishi kerak. «Текст ссылки»ga esa havolada ko'rinadigan yozuv yoziladi. A: «Добавьте собственное заявление», B: «Текст ссылки» (Link text), C: «Сообщение для лидов»."}, {"id": "q15", "image": "images/5-8/q15.jpg", "keep_order": true, "prompt": "Forma yuborilgandan keyingi oyna. Odam bir bosishda sizga qo'ng'iroq qilishi uchun qaysi tugmani tanlaysiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "a", "explanation": "A: «Позвонить компании» (Call business). Mijozning o'zi qo'ng'iroq qilsa, u xarid qilishga tayyorroq bo'ladi va suhbat osonroq kechadi. B: «Посмотреть сайт» (View website), C: «Посмотреть файл» (Download), D: «Текст призыва к действию»."}, {"id": "q16", "image": "images/5-8/q16.jpg", "prompt": "«Посмотреть сайт» tanlanganda «Ссылка» maydoni qizil bo'lib qoldi. Sababi nima?", "options": [{"id": "a", "text": "Formada savol juda ko'p"}, {"id": "b", "text": "Rasm o'lchami noto'g'ri"}, {"id": "c", "text": "Byudjet tugagan"}, {"id": "d", "text": "Bu maydonga haqiqiy sayt manzili yozilmagan, shuning uchun Facebook xato ko'rsatyapti"}], "correct_option_id": "d", "explanation": "Xato ostida ham yozilgan: «Укажите действительный URL сайта» — haqiqiy URL kiriting."}, {"id": "q17", "image": "images/5-8/q17.jpg", "prompt": "«Текст призыва к действию» maydoni bo'sh qolgani uchun xato chiqdi. Bu maydon nima uchun kerak?", "options": [{"id": "a", "text": "Facebook sahifa nomi uchun"}, {"id": "b", "text": "Tugatish oynasidagi tugmada yoziladigan matn uchun: tugma matnsiz bo'lishi mumkin emas"}, {"id": "c", "text": "Formaning nomi uchun"}, {"id": "d", "text": "Reklama sarlavhasi uchun"}], "correct_option_id": "b", "explanation": "Xatoda ham yozilgan: tashakkur sahifasida matnli tugma bo'lishi kerak. Ustoz bu yerga telefon raqamini yozdi."}, {"id": "q18", "image": "images/5-8/q18.jpg", "prompt": "Forma yuborilgandan keyin odam nimani ko'radi?", "options": [{"id": "a", "text": "«Thanks, you're all set» sarlavhasi, «Siz bilan tez orada bog'lanamiz» degan matn va qo'ng'iroq qilish tugmasi"}, {"id": "b", "text": "Yana o'sha formani boshidan"}, {"id": "c", "text": "Saytning bosh sahifasini"}, {"id": "d", "text": "Bo'sh oynani"}], "correct_option_id": "a", "explanation": "Bu «Сообщение для лидов» (Completion message), ya'ni formaning oxirgi oynasi."}, {"id": "q19", "image": "images/5-8/q19.jpg", "prompt": "Reklama preview'ida tugma ustida «ФОРМА НА FACEBOOK» deb yozilgan. Bu nimani bildiradi?", "options": [{"id": "a", "text": "Tugma ishlamaydi"}, {"id": "b", "text": "«Регистрация» tugmasi bosilganda sayt emas, Facebook'ning o'zidagi moment forma ochiladi"}, {"id": "c", "text": "Odam Facebook'ka ro'yxatdan o'tadi"}, {"id": "d", "text": "Reklama faqat Facebook'da ko'rsatiladi"}], "correct_option_id": "b", "explanation": "Odam ilovadan chiqmasdan ma'lumotlarini qoldiradi."}]$json$::jsonb, true)
on conflict (id) do update set title = excluded.title, questions = excluded.questions, section = excluded.section, section_order = excluded.section_order, lesson_order = excluded.lesson_order;

insert into public.tests(id, section, section_order, lesson_order, title, questions, published) values (
'5-9r', '5. Reklama kampaniyalari', 5, 9, '9. Lidlarni ko''chirish — rasmli 🖼', $json$[{"id": "q1", "image": "images/5-9/q1.jpg", "keep_order": true, "prompt": "Meta Business Suite ochiq. Moment formalardan kelgan lidlarni topish uchun chap menyuda qaysi bo'limni bosasiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "d", "explanation": "D: «Все инструменты» (All tools). «Все инструменты» ichida «Моментальные формы» (Instant forms) bo'limi bor. A: «Входящие» (Inbox), B: «Реклама» (Ads), C: «Статистика» (Insights)."}, {"id": "q2", "image": "images/5-9/q2.jpg", "keep_order": true, "prompt": "Formalar ro'yxati. BLENDER formasidan kelgan lidlarni faylga yuklab olish uchun qaysi tugmani bosasiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "a", "explanation": "A: «Скачать» (Download). Lidlar CSV yoki XLS faylda yuklanadi, keyin Excel'da ochiladi. B: «Действия» (Actions), C: «Продвигать» (Boost), D: «Создать форму» (Create form)."}, {"id": "q3", "image": "images/5-9/q3.jpg", "keep_order": true, "prompt": "Lidlar har safar yuklab olinmasdan, avtomatik CRM tizimiga tushishini xohlaysiz. Qaysi bo'limga kirasiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "a", "explanation": "A: «Настройка CRM» (CRM setup). Bu yerda CRM tizimi tanlanib, Facebook'ka ulanadi. B: «Черновики форм» (Form drafts), C: «Фильтры» (Filters), D: «Формы» (Forms)."}, {"id": "q4", "image": "images/5-9/q4.jpg", "prompt": "«Настройка CRM» sahifasida CRM tizimlari ro'yxati ochiq. CRM ulash nima beradi?", "options": [{"id": "a", "text": "Reklama bepul bo'ladi"}, {"id": "b", "text": "Formaga yangi savollar qo'shiladi"}, {"id": "c", "text": "Facebook sahifa o'chiriladi"}, {"id": "d", "text": "Lidlar avtomatik CRMga tushadi va har safar CSV faylni yuklab olish kerak bo'lmaydi"}], "correct_option_id": "d", "explanation": "Sahifadagi tavsifda ham shunday yozilgan: lidlarni CRM orqali avtomatik qo'shish va boshqarish mumkin."}, {"id": "q5", "image": "images/5-9/q5.jpg", "keep_order": true, "prompt": "amoCRM'da «Источники сделок» (Deal sources) oynasi ochiq. Facebook lid formalarini ulash uchun qaysi manbani qo'shasiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "a", "explanation": "A: «Facebook» — «Добавить». Keyin Facebook akkaunti, sahifa va forma tanlanadi. B: «Instagram» — «Добавить», C: «Конструктор форм» — «Добавить», D: «Telegram» — «Добавить»."}, {"id": "q6", "image": "images/5-9/q6.jpg", "keep_order": true, "prompt": "amoCRM'dagi Facebook vositalari. Moment formadan kelgan lidlarni olish uchun qaysi bo'limni tanlaysiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "c", "explanation": "C: «Форма Facebook» — «Добавить форму». Forma tanlanib saqlangach, yangi lidlar o'zi amoCRMga tushadi. A: «Messenger» — «Добавить страницу», B: «Реклама Facebook», D: «Комментарии» — «Добавить страницу»."}]$json$::jsonb, true)
on conflict (id) do update set title = excluded.title, questions = excluded.questions, section = excluded.section, section_order = excluded.section_order, lesson_order = excluded.lesson_order;

insert into public.tests(id, section, section_order, lesson_order, title, questions, published) values (
'5-10r', '5. Reklama kampaniyalari', 5, 10, '10. Purchase maqsadi — rasmli 🖼', $json$[{"id": "q1", "image": "images/5-10/q1.jpg", "keep_order": true, "prompt": "Saytdan sotuv olish uchun reklama yaratmoqchisiz. Qaysi kampaniya maqsadini tanlaysiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "b", "explanation": "B: «Продажи» (Sales). Sotuv maqsadida Facebook xarid qiladigan odamlarni qidiradi. A: «Узнаваемость» (Awareness), C: «Лиды» (Leads), D: «Трафик» (Traffic)."}, {"id": "q2", "image": "images/5-10/q2.jpg", "keep_order": true, "prompt": "«Продажи» kampaniyasining reklama guruhi. Facebook aynan xarid qiladigan odamlarni qidirishi uchun qaysi maydonda «Покупка» tanlanadi?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "b", "explanation": "B: «Событие конверсии» (Conversion event). «Покупка» (Purchase) eventi saytga oldindan o'rnatilgan bo'lishi kerak. A: «Пиксель» (Pixel), C: «Цель по результативности», D: «Цель по цене за результат»."}, {"id": "q3", "image": "images/5-10/q3.jpg", "prompt": "Ads Manager jadvalining pastki qatoriga qarang. Barcha kampaniyalar bo'yicha jami nechta xarid (покупка) bo'lgan?", "options": [{"id": "a", "text": "49 ta, ularning umumiy qiymati 38 400 $"}, {"id": "b", "text": "1 ta"}, {"id": "c", "text": "29 ta"}, {"id": "d", "text": "2 875 ta"}], "correct_option_id": "a", "explanation": "Pastki «Результаты 29 кампаний» qatorida «Покупки» ustunida 49, «Ценность конверсии покупок» ustunida 38 400 $ yozilgan."}, {"id": "q4", "image": "images/5-10/q4.jpg", "keep_order": true, "prompt": "Jadvalda pastdagi harflar ustunlarni ko'rsatadi. Bitta xarid o'rtacha necha dollarga tushganini qaysi ustundan ko'rasiz?", "options": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "C"}, {"id": "d", "text": "D"}], "correct_option_id": "b", "explanation": "B: «Цена за покупку» (Cost per purchase). Jami bo'yicha bitta xarid o'rtacha 58,69 $ ga tushgan. A: «Сумма затрат» (Amount spent), C: «Ценность конверсии покупок» (Purchase value), D: «Покупки» (Purchases)."}]$json$::jsonb, true)
on conflict (id) do update set title = excluded.title, questions = excluded.questions, section = excluded.section, section_order = excluded.section_order, lesson_order = excluded.lesson_order;
